    let dy;
    let dist_1;
    let dist_2;

    dx = (cptr.ldI16(u) - cptr.ldI16(c1)) | 0;
    dy = (cptr.ldI16o(u, $you_uy) - cptr.ldI16o(c1, $coord_y)) | 0;
