/* format increased chance to hit or damage or defense (Protection) */
/**
 * C ref: insight.c:160
 * @param {CPtr<char>} inctyp
 * @param {CInt} incamt
 * @param {CInt} final
 * @param {CPtr<char>} outbuf
 * @returns {CPtr<char>}
 */
function* enlght_combatinc(inctyp, incamt, final, outbuf) {
    let modif;
    let bonus;
    let invrt;
    let absamt;

    absamt = Math.abs(incamt);
    /* Protection amount is typically larger than damage or to-hit;
       reduce magnitude by a third in order to stretch modifier ranges
       (small:1..5, moderate:6..10, large:11..19, huge:20+) */
    if (!strcmp(inctyp, __s_defense))
        absamt = ((Math.imul(absamt, 2)) / 3) | 0;

    if (absamt <= 3)
        modif = __s_small;
    else if (absamt <= 6)
        modif = __s_moderate;
    else if (absamt <= 12)
        modif = __s_large;
    else
        modif = __s_huge;

    modif = !incamt ? __s_no : (yield* an(modif));  /* ("no" case shouldn't happen) */
    bonus = (incamt >= 0) ? __s_bonus : __s_penalty;
    /* "bonus <foo>" (to hit) vs "<bar> bonus" (damage, defense) */
    invrt = schar((strcmp(inctyp, __s_to_hit) ? 1 : 0));

    void cptr.sprintf(outbuf, __s_s_s_s$insight, modif, invrt ? inctyp : bonus, invrt ? bonus : inctyp);
    if (final || wizard())
        void cptr.sprintf(eos(outbuf), __s_s_d$insight, (incamt > 0) ? __s_plus : __s_empty$insight, incamt);

    return outbuf;
}

