            (yield* uncurse(otmp));
        cptr.stI32o(otmp, $obj_known, 1);
        (yield* setworn(otmp, 1n));
        if ((cptr.ldI32o(otmp, $obj_unpaid) & 1))
            (yield* alter_cost(otmp, 0n));  /* shop bill */
        cptr.stI32o(otmp, $obj_lamplit, was_lit);
