/* pick a tool for autounlock */
/** C ref: lock.c:289 — @param {CInt} opening @returns {CPtr<struct obj>} */
function autokey(opening) {
    let o;
    let key;
    let pick;
    let card;
    let akey;
    let apick;
    let acard;

    /* mundane item or regular artifact or own role's quest artifact */
    key = (pick = (card = null));
    /* other role's quest artifact (Rogue's Key or Tourist's Credit Card) */
    akey = (apick = (acard = null));
    for (o = cptr.ldPtro(gi, $instance_globals_i_invent); o; o = cptr.ldPtr(o)) {
        if ((cptr.ld1so((o), $obj_oartifact) >= NHC.ART_ORB_OF_DETECTION) &&
                !is_quest_artifact(o)) {
            switch (cptr.ldI16o(o, $obj_otyp)) {
                case NHC.SKELETON_KEY:
                    if (!akey)
                        akey = o;
                    break;
                case NHC.LOCK_PICK:
                    if (!apick)
                        apick = o;
                    break;
                case NHC.CREDIT_CARD:
                    if (!acard)
                        acard = o;
                    break;
                default:
                    break;
            }
        } else {
            switch (cptr.ldI16o(o, $obj_otyp)) {
                case NHC.SKELETON_KEY:
                    if (!key || is_magic_key(cptr.add(gy, $instance_globals_y_youmonst), o))
                        key = o;
                    break;
                case NHC.LOCK_PICK:
                    if (!pick)
                        pick = o;
                    break;
                case NHC.CREDIT_CARD:
                    if (!card)
                        card = o;
                    break;
                default:
                    break;
            }
        }
    }
    if (!opening)
        card = (acard = null);
    /* only resort to other role's quest artifact if no other choice */
    if (!key && !pick && !card)
        key = akey;
    if (!pick && !card)
        pick = apick;
    if (!card)
        card = acard;
    return key ? key : (pick ? pick : (card ? card : null));
}

