/** C ref: mkmaze.c:799 */
function* stolen_booty() {
    let gang;
    let gang_name = new Uint8Array(256);
    let mtmp;
    let cnt;
    let i;
    let otyp;

    /*
     * --------------------------------------------------------
     * Mythos:
     *
     *      A tragic accident has occurred in Frontier Town...
     *      It has been overrun by orcs.
     *
     *      The booty that the orcs took from the town is now
     *      in the possession of the orcs that did this and
     *      have long since fled the level.
     * --------------------------------------------------------
     */

    gang = rndorcname(cptr.decay(gang_name));
    /* create the stuff that the gang took */
    cnt = rnd(4);
    for (i = 0; i < cnt; ++i)
        (yield* migr_booty_item(rn2(4) ? NHC.TALLOW_CANDLE : NHC.WAX_CANDLE, gang));
    cnt = rnd(3);
    for (i = 0; i < cnt; ++i)
        (yield* migr_booty_item(NHC.SKELETON_KEY, gang));
    otyp = ((rn2(((NHC.GAUNTLETS_OF_DEXTERITY - NHC.LEATHER_GLOVES + 1) | 0)) +
            NHC.LEATHER_GLOVES) | 0);
    (yield* migr_booty_item(otyp, gang));
    cnt = rnd(10);
    for (i = 0; i < cnt; ++i) {
        /* Food items - but no lembas! (or some other weird things) */
        otyp = ((rn2(((NHC.TIN - NHC.TRIPE_RATION + 1) | 0)) + NHC.TRIPE_RATION) | 0);
        if (otyp != NHC.LEMBAS_WAFER &&
                (cptr.ldI16o2(objects, otyp, $sizeof_objclass, $objclass_oc_prob) != 0 ||
                    otyp == NHC.C_RATION ||
                    otyp == NHC.K_RATION) &&
                otyp != NHC.CORPSE &&
                otyp != NHC.EGG &&
                otyp != NHC.TIN)
            (yield* migr_booty_item(otyp, gang));
    }
    (yield* migr_booty_item(rn2(2) ? NHC.LONG_SWORD : NHC.SILVER_SABER, gang));
    /* create the leader of the orc gang */
    mtmp = (yield* makemon(cptr.add(mons, NHC.PM_ORC_CAPTAIN, $sizeof_permonst), 0, 0, NHM.MM_NONAME));
    if (mtmp) {
        mtmp = (yield* christen_monst(mtmp, upstart(gang)));
        cptr.stI32o(mtmp, $monst_mpeaceful, 0);
        set_malign(mtmp);
        (yield* shiny_orc_stuff(mtmp));
        (yield* migrate_orc(mtmp, 1n));
    }
    /* Make most of the orcs on the level be part of the invading gang */
    for (
        mtmp = cptr.ldPtro(svl, $instance_globals_saved_l_level + $dlevel_t_monlist);
        mtmp;
        mtmp = cptr.ldPtr(mtmp)
    ) {
        if ((cptr.ldI32o((mtmp), $monst_mhp) < 1))
            continue;

        if (((cptr.ldU64o((cptr.ldPtro(mtmp, $monst_data)), $permonst_mflags2) & 128n) != 0n) &&
                !has_mgivenname(mtmp) &&
                rn2(10)) {
            /*
             * We'll consider the orc captain from the level
             * description to be the captain of a rival orc horde
             * who is there to see what has transpired, and to
             * contemplate future action.
             *
             * Don't christen the orc captain as a subordinate
             * member of the main orc horde.
             */
            if (!cptr.eq(
                cptr.ldPtro(mtmp, $monst_data),
                cptr.add(mons, NHC.PM_ORC_CAPTAIN, $sizeof_permonst)
            ))
                mtmp = (yield* christen_orc(mtmp, upstart(gang), __s_empty$mkmaze));
        }
    }
    /* Lastly, ensure there's several more orcs from the gang along the way.
     * The mechanics are such that they aren't actually identified as
     * members of the invading gang until they get their spoils assigned
     * to the inventory; handled during that assignment.
     */
    cnt = (rn2(10) + 5) | 0;
    for (i = 0; i < cnt; ++i) {
        let mtyp;

        mtyp = (rn2(((NHC.PM_ORC_SHAMAN - NHC.PM_ORC + 1) | 0)) + NHC.PM_ORC) | 0;
        mtmp = (yield* makemon(cptr.add(mons, mtyp, $sizeof_permonst), 0, 0, NHM.MM_NONAME));
        if (mtmp) {
            (yield* shiny_orc_stuff(mtmp));
            (yield* migrate_orc(mtmp, 0n));
        }
    }
    cptr.st1o(gr, $instance_globals_r_ransacked, 0);
}

