/* Create a maze with specified corridor width and wall thickness
 * TODO: rewrite walkfrom so it works on temp space, not levl
 */
/** C ref: mkmaze.c:950 — @param {CInt} corrwid @param {CInt} wallthick @param {CInt} rmdeadends */
function* create_maze(corrwid, wallthick, rmdeadends) {
    let x;
    let y;
    let mm = cptr.alloc(4);
    let tmp_xmax = cptr.ldI32(gx);
    let tmp_ymax = cptr.ldI32(gy);
    let rdx = 0;
    let rdy = 0;
    let scale;

    if (corrwid == -1)
        corrwid = rnd(4);

    if (wallthick == -1)
        wallthick = (rnd(4) - corrwid) | 0;

    if (wallthick < 1)
        wallthick = 1;
    else if (wallthick > 5)
        wallthick = 5;

    if (corrwid < 1)
        corrwid = 1;
    else if (corrwid > 5)
        corrwid = 5;

    scale = (corrwid + wallthick) | 0;
    rdx = ((cptr.ldI32(gx) / scale) | 0);
    rdy = ((cptr.ldI32(gy) / scale) | 0);

    if ((cptr.ldI32o(
        svl,
        $instance_globals_saved_l_level + $dlevel_t_flags + $levelflags_corrmaze
    ) & 1))
        for (x = 2; x < (Math.imul(rdx, 2)); x++)
            for (y = 2; y < (Math.imul(rdy, 2)); y++)
                cptr.st1o3(
                    svl,
                    x,
                    $sizeof_rm_x21,
                    y,
                    $sizeof_rm,
                    $instance_globals_saved_l_level + $rm_typ,
                    NHC.STONE
                );
    else
        for (x = 2; x <= (Math.imul(rdx, 2)); x++)
            for (y = 2; y <= (Math.imul(rdy, 2)); y++)
                cptr.st1o3(
                    svl,
                    x,
                    $sizeof_rm_x21,
                    y,
                    $sizeof_rm,
                    $instance_globals_saved_l_level + $rm_typ,
                    schar((((x % 2) && (y % 2)) ? NHC.STONE : NHC.HWALL))
                );

    /* set upper bounds for maze0xy and walkfrom */
    cptr.stI32(gx, (Math.imul(rdx, 2)));
    cptr.stI32(gy, (Math.imul(rdy, 2)));

    /* create maze */
    maze0xy(mm);
    (yield* walkfrom(i16(cptr.ldI16(mm)), i16(cptr.ldI16o(mm, $nhcoord_y)), 0));

    if (rmdeadends)
        (yield* maze_remove_deadends(i16((((cptr.ldI32o(
            svl,
            $instance_globals_saved_l_level + $dlevel_t_flags + $levelflags_corrmaze
        ) & 1)) | 0
                ? NHC.CORR
                : NHC.ROOM))));

    /* restore bounds */
    cptr.stI32(gx, tmp_xmax);
    cptr.stI32(gy, tmp_ymax);

    /* scale maze up if needed */
    if (scale > 2) {
        let tmpmap = (function () {
            const flat = new Uint8Array(80 * (21 * 1));
            const a = [];
            for (let r = 0; r < 80; r++) a.push(flat.subarray(r * (21 * 1), (r + 1) * (21 * 1)));
            a.buf = flat;
            return a;
        })();
        let mx;
        let my;
        let dx;
        let dy;
        let rx = 1;
        let ry = 1;

        /* back up the existing smaller maze */
        for (x = 1; x < cptr.ldI32(gx); x++)
            for (y = 1; y < cptr.ldI32(gy); y++) {
                cptr.st1o(
                    cptr.decay(tmpmap[x]),
                    y,
                    cptr.ld1so3(
                        svl,
                        x,
                        $sizeof_rm_x21,
                        y,
                        $sizeof_rm,
                        $instance_globals_saved_l_level + $rm_typ
                    ),
                    1
                );
            }

        /* do the scaling */
        rx = (x = 2);
        while (rx < cptr.ldI32(gx)) {
            mx = (x % 2) ? corrwid : ((x == 2 || x == Math.imul(rdx, 2)) ? 1 : wallthick);
            ry = (y = 2);
            while (ry < cptr.ldI32(gy)) {
                my = (y % 2) ? corrwid : ((y == 2 || y == Math.imul(rdy, 2)) ? 1 : wallthick);
                for (dx = 0; dx < mx; dx++)
                    for (dy = 0; dy < my; dy++) {
                        if (((rx + dx) | 0) >= cptr.ldI32(gx) || ((ry + dy) | 0) >= cptr.ldI32(gy))
                            break;
                        cptr.st1o3(
                            svl,
                            (rx + dx) | 0,
                            $sizeof_rm_x21,
                            (ry + dy) | 0,
                            $sizeof_rm,
                            $instance_globals_saved_l_level + $rm_typ,
                            cptr.ld1so(cptr.decay(tmpmap[x]), y, 1)
                        );
                    }
                ry = (ry + my) | 0;
                y++;
            }
            rx = (rx + mx) | 0;
            x++;
        }

    }
}

/** C ref: mkmaze.c:1042 */
function* pick_vibrasquare_location() {
    let x;
    let y;
    let stway;
    let trycnt = 0;
    let x_range = (cptr.ldI32(gx) - 2 - 8 - 1) | 0;
    let y_range = (cptr.ldI32(gy) - 2 - 6 - 1) | 0;

    if (x_range <= 4 || y_range <= 3 || (Math.imul(x_range, y_range)) <= 121) {
        {
            if ((yield* debugcore(__s_mkmaze_c, 1))) {
                let save_plnmsg = cptr.ldI32o(iflags, $instance_flags_last_msg);
                (yield* pline(__s_svi_inv_pos_maze_is_too_small_d_x_d, cptr.ldI32(gx), cptr.ldI32(gy)));
                cptr.stI32o(iflags, $instance_flags_last_msg, save_plnmsg);
            }
        }
    }
    cptr.stI16(svi, cptr.stI16o(svi, $nhcoord_y, 0));  /*{occupied() => invocation_pos()}*/
    do {
        x = i16(((rn2(x_range) + 7) | 0));
        y = i16(((rn2(y_range) + 6) | 0));
        /* we don't want it to be too near the stairs, nor
           to be on a spot that's already in use (wall|trap) */
        if (++trycnt > 1000)
            break;
    } while (((stway = stairway_find_dir(1)) !== null) &&
            (x == cptr.ldI16(stway) ||
                y == cptr.ldI16o(stway, $stairway_sy) ||
                Math.abs((x - cptr.ldI16(stway)) | 0) ==
                    Math.abs((y - cptr.ldI16o(stway, $stairway_sy)) | 0) ||
                distmin(x, y, cptr.ldI16(stway), cptr.ldI16o(stway, $stairway_sy)) <= 11 ||
                !((cptr.ld1so3(
                    svl,
                    x,
                    $sizeof_rm_x21,
                    y,
                    $sizeof_rm,
                    $instance_globals_saved_l_level + $rm_typ
                )) >
                    NHC.DOOR) ||
                occupied(x, y)));
    cptr.stI16(svi, x);
    cptr.stI16o(svi, $nhcoord_y, y);
}

/* add objects and monsters to random maze */
/** C ref: mkmaze.c:1097 */
function* populate_maze() {
    let i;
    let mm = cptr.alloc(4);

    for (i = ((rn2(8) + 11) | 0); i; i--) {
        (yield* mazexy(mm));
        void (yield* mkobj_at(
            schar((rn2(2) ? NHC.GEM_CLASS : NHC.RANDOM_CLASS)),
            cptr.ldI16(mm),
            cptr.ldI16o(mm, $nhcoord_y),
            1
        ));
    }
    for (i = ((rn2(10) + 2) | 0); i; i--) {
        (yield* mazexy(mm));
        void (yield* mksobj_at(NHC.BOULDER, cptr.ldI16(mm), cptr.ldI16o(mm, $nhcoord_y), 1, 0));
    }
    for (i = rn2(3); i; i--) {
        (yield* mazexy(mm));
        void (yield* makemon(
            cptr.add(mons, NHC.PM_MINOTAUR, $sizeof_permonst),
            cptr.ldI16(mm),
            cptr.ldI16o(mm, $nhcoord_y),
            NHM.NO_MM_FLAGS
        ));
    }
    for (i = ((rn2(5) + 7) | 0); i; i--) {
        (yield* mazexy(mm));
        void (yield* makemon(null, cptr.ldI16(mm), cptr.ldI16o(mm, $nhcoord_y), NHM.NO_MM_FLAGS));
    }
    for (i = ((rn2(6) + 7) | 0); i; i--) {
        (yield* mazexy(mm));
        void (yield* mkgold(0n, cptr.ldI16(mm), cptr.ldI16o(mm, $nhcoord_y)));
    }
    for (i = ((rn2(6) + 7) | 0); i; i--)
        (yield* mktrap(0, NHM.MKTRAP_MAZEFLAG, null, null));
}

