/** C ref: mklev.c:439 — @param {CInt} a @param {CInt} b @param {CInt} nxcor */
function* join(a, b, nxcor) {
    let cc = cptr.alloc(4);
    let tt = cptr.alloc(4);
    let org = cptr.alloc(4);
    let dest = cptr.alloc(4);
    let tx;
    let ty;
    let xx;
    let yy;
    let croom;
    let troom;
    let dx;
    let dy;
    let npoints = cptr.box(0);
    let dig_result;

    croom = cptr.add(svr, a, $sizeof_mkroom);
    troom = cptr.add(svr, b, $sizeof_mkroom);

    if (!cptr.ld1so(croom, $mkroom_needjoining) || !cptr.ld1so(troom, $mkroom_needjoining))
        return;

    /* find positions cc and tt for doors in croom and troom
       and direction for a corridor between them */

    if (cptr.ldI16o(troom, $mkroom_hx) < 0 || cptr.ldI16o(croom, $mkroom_hx) < 0)
        return;
    if (cptr.ldI16(troom) > cptr.ldI16o(croom, $mkroom_hx)) {
        dx = 1;
        dy = 0;
        if (!(yield* finddpos(cc, NHC.DIR_E, croom)))
            return;
        if (!(yield* finddpos(tt, NHC.DIR_W, troom)))
            return;
    } else if (cptr.ldI16o(troom, $mkroom_hy) < cptr.ldI16o(croom, $mkroom_ly)) {
        dy = -1;
        dx = 0;
        if (!(yield* finddpos(cc, NHC.DIR_N, croom)))
            return;
        if (!(yield* finddpos(tt, NHC.DIR_S, troom)))
            return;
    } else if (cptr.ldI16o(troom, $mkroom_hx) < cptr.ldI16(croom)) {
        dx = -1;
        dy = 0;
        if (!(yield* finddpos(cc, NHC.DIR_W, croom)))
            return;
        if (!(yield* finddpos(tt, NHC.DIR_E, troom)))
            return;
    } else {
        dy = 1;
        dx = 0;
        if (!(yield* finddpos(cc, NHC.DIR_S, croom)))
            return;
        if (!(yield* finddpos(tt, NHC.DIR_N, troom)))
            return;
    }
    xx = cptr.ldI16(cc);
    yy = cptr.ldI16o(cc, $nhcoord_y);
    tx = i16(((cptr.ldI16(tt) - dx) | 0));
    ty = i16(((cptr.ldI16o(tt, $nhcoord_y) - dy) | 0));
    if (nxcor &&
            cptr.ld1so3(
                svl,
                (xx + dx) | 0,
                $sizeof_rm_x21,
                (yy + dy) | 0,
                $sizeof_rm,
                $instance_globals_saved_l_level + $rm_typ
            ) !=
                NHC.STONE)
        return;

    cptr.stI16(org, i16(((xx + dx) | 0)));
    cptr.stI16o(org, $nhcoord_y, i16(((yy + dy) | 0)));
    cptr.stI16(dest, tx);
    cptr.stI16o(dest, $nhcoord_y, ty);

    dig_result = (yield* dig_corridor(
        org,
        dest,
        npoints,
        nxcor,
        schar(((cptr.ldI32o(
            svl,
            $instance_globals_saved_l_level + $dlevel_t_flags + $levelflags_arboreal
        ) & 1) | 0
            ? NHC.ROOM
            : NHC.CORR)),
        NHC.STONE
    ));

    /* we created at least 1 tile of corridor, even if it failed */
    if ((npoints.v > 0) && (okdoor(xx, yy) || !nxcor))
        (yield* dodoor(xx, yy, croom));

    if (!dig_result)
        return;

    /* we succeeded in digging the corridor */
    if (okdoor(cptr.ldI16(tt), cptr.ldI16o(tt, $nhcoord_y)) || !nxcor)
        (yield* dodoor(cptr.ldI16(tt), cptr.ldI16o(tt, $nhcoord_y), troom));

    if (cptr.ldI32o2(gs, a, 4, $instance_globals_s_smeq) <
            cptr.ldI32o2(gs, b, 4, $instance_globals_s_smeq))
        cptr.stI32o2(
            gs,
            b,
            4,
            $instance_globals_s_smeq,
            cptr.ldI32o2(gs, a, 4, $instance_globals_s_smeq)
        );
    else
        cptr.stI32o2(
            gs,
            a,
            4,
            $instance_globals_s_smeq,
            cptr.ldI32o2(gs, b, 4, $instance_globals_s_smeq)
        );
}

/* create random corridors between rooms */
/** C ref: mklev.c:522 */
function* makecorridors() {
    let a;
    let b;
    let i;
    let any = 1;

    for (a = 0; a < ((cptr.ldI32o(svn, $instance_globals_saved_n_nroom) - 1) | 0); a++) {
        (yield* join(a, (a + 1) | 0, 0));
        if (!rn2(50))
            break;  /* allow some randomness */
    }
    for (a = 0; a < ((cptr.ldI32o(svn, $instance_globals_saved_n_nroom) - 2) | 0); a++)
        if (cptr.ldI32o2(gs, a, 4, $instance_globals_s_smeq) !=
                cptr.ldI32o2(gs, (a + 2) | 0, 4, $instance_globals_s_smeq))
            (yield* join(a, (a + 2) | 0, 0));
    for (a = 0; any && a < cptr.ldI32o(svn, $instance_globals_saved_n_nroom); a++) {
        any = 0;
        for (b = 0; b < cptr.ldI32o(svn, $instance_globals_saved_n_nroom); b++)
            if (cptr.ldI32o2(gs, a, 4, $instance_globals_s_smeq) !=
                    cptr.ldI32o2(gs, b, 4, $instance_globals_s_smeq)) {
                (yield* join(a, b, 0));
                any = 1;
            }
    }
    /* add some extra corridors which may be blocked off */
    if (cptr.ldI32o(svn, $instance_globals_saved_n_nroom) > 2)
        for (i = (rn2(cptr.ldI32o(svn, $instance_globals_saved_n_nroom)) + 4) | 0; i; i--) {
            a = rn2(cptr.ldI32o(svn, $instance_globals_saved_n_nroom));
            b = rn2((cptr.ldI32o(svn, $instance_globals_saved_n_nroom) - 2) | 0);
            if (b >= a)
                b = (b + 2) | 0;
            (yield* join(a, b, 1));
        }
}

