/* make a swarm of undead around mm */
/**
 * C ref: mkroom.c:456
 * @param {CPtr<coord>} mm
 * @param {CInt} revive_corpses
 * @param {CInt} mm_flags
 */
function* mkundead(mm, revive_corpses, mm_flags) {
    let cnt = ((((((yield* level_difficulty()) + 1) | 0) / 10) | 0) + rnd(5)) | 0;
    let mdat;
    let otmp;
    let cc = cptr.alloc(4);

    while (cnt--) {
        mdat = (yield* morguemon());
        if (mdat &&
                (yield* enexto(cc, cptr.ldI16(mm), cptr.ldI16o(mm, $coord_y), mdat)) &&
                (!revive_corpses ||
                    !(otmp = sobj_at(NHC.CORPSE, cptr.ldI16(cc), cptr.ldI16o(cc, $nhcoord_y))) ||
                    !(yield* revive(otmp, 0))))
            void (yield* makemon(mdat, cptr.ldI16(cc), cptr.ldI16o(cc, $nhcoord_y), mm_flags >>> 0));
    }
    cptr.stI32o(svl, $instance_globals_saved_l_level + $dlevel_t_flags + $levelflags_graveyard, 1);  /* reduced chance for undead corpse */
}

/** C ref: mkroom.c:478 @returns {CPtr<struct permonst>} */
function* morguemon() {
    let i = rn2(100);
    let hd = rn2((yield* level_difficulty()));

    if (hd > 10 && i < 10) {
        if (In_hell(cptr.add(u, $you_uz)) ||
                (cptr.ldI16((cptr.add(u, $you_uz))) ==
                    cptr.ldI16((cptr.add(
                        svd,
                        $instance_globals_saved_d_dungeon_topology + $dgn_topology_d_astral_level
                    ))))) {
            return (yield* mkclass(NHC.S_DEMON, 0));
        } else {
            let ndemon_res = (yield* ndemon(-128));
            if (ndemon_res != NHC.NON_PM)
                return cptr.add(mons, ndemon_res, $sizeof_permonst);
            /* else do what? As is, it will drop to ghost/wraith/zombie */
        }
    }

    if (hd > 8 && i > 85)
        return (yield* mkclass(NHC.S_VAMPIRE, 0));

    return ((i < 20)
            ? cptr.add(mons, NHC.PM_GHOST, $sizeof_permonst)
            : ((i < 40)
                ? cptr.add(mons, NHC.PM_WRAITH, $sizeof_permonst)
                : (yield* mkclass(NHC.S_ZOMBIE, 0))));
}

