/**
 * C ref: minion.c:361
 * @param {CPtr<struct monst>} mtmp
 * @param {CPtr<char>} prompt
 * @returns {CLongLong}
 */
function* bribe(mtmp, prompt) {
    let buf = [0];
    let offer = cptr.box(0n);
    let umoney = money_cnt(cptr.ldPtro(gi, $instance_globals_i_invent));

    (yield* getlin(prompt, cptr.decay(buf)));
    if (sscanf(cptr.decay(buf), __s_ld$minion, offer) != 1)
        offer.v = 0n;

    /*Michael Paddon -- fix for negative offer to monster*/
    /*JAR880815 - */
    if (offer.v < 0n) {
        (yield* You(__s_try_to_shortchange_s_but_fumble, (yield* mon_nam(mtmp))));
        return 0n;
    } else if (offer.v == 0n) {
        (yield* You(__s_refuse));
        return 0n;
    } else if (offer.v >= umoney) {
        (yield* You(__s_give_s_all_your_gold, (yield* mon_nam(mtmp))));
        offer.v = umoney;
    } else {
        (yield* You(__s_give_s_ld_s, (yield* mon_nam(mtmp)), offer.v, (yield* currency(offer.v))));
    }
    void (yield* money2mon(mtmp, offer.v));
    cptr.st1(disp, 1);
    return offer.v;
}

