const ArgVal_novalue = cptr.bytes("[nothing]");

/** C ref: earlyarg.c:56 — enum */
const ArgValRequired = 0;
const ArgValOptional = 1;
const ArgValDisallowed = 2;
const ArgVal_mask = 3;
const ArgNamOneLetter = 4;
const ArgNam_mask = 4;
const ArgErrSilent = 0;
const ArgErrComplain = 8;
const ArgErr_mask = 8;

/* approximate 'getopt_long()' for one option; all the comments refer to
   "-windowtype" but the code isn't specific to that  */
/**
 * C ref: earlyarg.c:71
 * @param {CPtr<char>} arg
 * @param {CInt} lflags
 * @param {CPtr<char>} optname
 * @param {CPtr<char>} origarg
 * @param {CPtr<int>} argc_p
 * @param {CPtr<char **>} argv_p
 * @returns {CPtr<char>}
 */
function* lopt(arg, lflags, optname, origarg, argc_p, argv_p) {
    let argc = cptr.ldI32(argc_p);
    let argv = cptr.ldPtr(argv_p);
    let p;
    let nextarg = (argc > 1 && cptr.ld1so(cptr.ldPtro(argv, 1, 8), 0) != 45)
            ? cptr.ldPtro(argv, 1, 8)
            : null;
    let l;
    let opttype = (lflags & NHC.ArgVal_mask);
    let oneletterok = schar(((lflags & NHC.ArgNam_mask) == NHC.ArgNamOneLetter));
    let complain = schar(((lflags & NHC.ArgErr_mask) == NHC.ArgErrComplain));

    /* first letter must match */
    if (cptr.ld1so(arg, 1) != cptr.ld1so(optname, 1)) {
        if (complain)
            (yield* config_error_add(__s_unknown_option_60s, origarg));
        return null;
    }

    if ((p = cptr.strchr(arg, 61)) === null)
        p = cptr.strchr(arg, 58);
    if (p && opttype == NHC.ArgValDisallowed)
        {
            if (complain)
                (yield* config_error_add(__s_value_not_allowed_60s, origarg));
            return null;
        }

    l = Number(BigInt.asIntN(32, (p ? (cptr.diff(p, arg)) : BigInt.asIntN(64, cptr.strlen(arg)))));
    if ((l > 2 || oneletterok) && !cptr.strncmp(arg, optname, BigInt.asUintN(64, BigInt(l)))) {
        /* "-windowtype[=foo]" */
        if (p)
            p = cptr.add(p, 1);  /* past '=' or ':' */
        else if (opttype == NHC.ArgValRequired)
            p = eos(arg);
        else
            return cptr.decay(ArgVal_novalue);
    } else if (oneletterok) {
        /* "-w..." but not "-w[indowtype[=foo]]" */
        if (!p) {
            p = cptr.add(arg, 2);  /* past 'w' of "-wfoo" */
        } else {
            /* "-w...=foo" but not "-w[indowtype]=foo" */
            {
                if (complain)
                    (yield* config_error_add(__s_unknown_option_60s, origarg));
                return null;
            }
        }
    } else {
        {
            if (complain)
                (yield* config_error_add(__s_unknown_option_60s, origarg));
            return null;
        }
    }
    if (!p || !cptr.ld1s(p)) {
        /* "-w[indowtype]" w/o '='/':' if there is a next element, use
           it for "foo"; if not, supply a non-Null bogus value */
        if (nextarg && (opttype == NHC.ArgValRequired || opttype == NHC.ArgValOptional))
            p = nextarg,
                    cptr.stI32(argc_p, cptr.ldI32(argc_p) + -1),
                    cptr.preinc(() => cptr.ldPtr(argv_p), (v) => { cptr.stPtr(argv_p, v); }, 8);
        else if (opttype == NHC.ArgValRequired)
            {
                if (complain)
                    (yield* config_error_add(__s_missing_required_value_60s, origarg));
                return null;
            }
        else
            p = cptr.decay(ArgVal_novalue);  /* there is no next element */
    }
    return p;
}

/* move argv[ndx] to end of argv[] array, then reduce argc to hide it;
   prevents process_options() from encountering it after early_options()
   has processed it; elements get reordered but all remain intact */
/** C ref: earlyarg.c:149 — @param {CInt} ndx @param {CPtr<int>} ac_p @param {CPtr<char **>} av_p */
function consume_arg(ndx, ac_p, av_p) {
    let gone;
    let av = cptr.ldPtr(av_p);
    let i;
    let ac = cptr.ldI32(ac_p);

    /* "-one -two -three -four" -> "-two -three -four -one" */
    if (ac > 2) {
        gone = cptr.ldPtro(av, ndx, 8);
        for (i = (ndx + 1) | 0; i < ac; ++i)
            cptr.stPtro(av, (i - 1) | 0, cptr.ldPtro(av, i, 8), 8);
        cptr.stPtro(av, (ac - 1) | 0, gone, 8);
    }
    cptr.stI32(ac_p, cptr.ldI32(ac_p) + -1);
}

/* consume two tokens for '-argname value' w/o '=' or ':' */
/** C ref: earlyarg.c:166 — @param {CInt} ndx @param {CPtr<int>} ac_p @param {CPtr<char **>} av_p */
function consume_two_args(ndx, ac_p, av_p) {
    /* when consuming "-two arg" from "-two arg -three -four",
       the *ac_p manipulation results in "-three -four -two arg"
       rather than the "-three -four arg -two" that would happen
       with just two ordinary consume_arg() calls */
    consume_arg(ndx, ac_p, av_p);
    cptr.stI32(ac_p, cptr.ldI32(ac_p) + 1);  /* bring the final slot back into view */
    consume_arg(ndx, ac_p, av_p);
    cptr.stI32(ac_p, cptr.ldI32(ac_p) + -1);  /* take away restored slot */
}

/* process some command line arguments before loading options */
/**
 * C ref: earlyarg.c:180
 * @param {CPtr<int>} argc_p
 * @param {CPtr<char **>} argv_p
 * @param {CPtr<char *>} hackdir_p
 */
function* early_options(argc_p, argv_p, hackdir_p) {
    let argv = cptr.box(0);
    let arg;
    let origarg;
    let argc = cptr.box(0);
    let oldargc;
    let ndx = 0;
    let consumed = 0;
    if ((yield* argcheck(cptr.ldI32(argc_p), cptr.ldPtr(argv_p), NHC.ARG_DUMPGLYPHIDS)) == 2)
        (yield* opt_terminate());

    (yield* config_error_init(0, __s_command_line$earlyarg, 0));

    /* treat "nethack ?" as a request for usage info; due to shell
       processing, player likely has to use "nethack \?" or "nethack '?'"
       [won't work if used as "nethack -dpath ?" or "nethack -d path ?"] */
    if (cptr.ldI32(argc_p) > 1 && !strcmp(cptr.ldPtro((cptr.ldPtr(argv_p)), 1, 8), __s_query$earlyarg))
        (yield* opt_usage(cptr.ldPtr(hackdir_p)));  /* doesn't return */

    /*
     * Both *argc_p and *argv_p account for the program name as (*argv_p)[0];
     * local argc and argv implicitly discard that (by starting 'ndx' at 1).
     * argcheck() doesn't mind, prscore() (via scores_only()) does (for the
     * number of args it gets passed, not for the value of argv[0]).
     */
    for (ndx = 1; ndx < cptr.ldI32(argc_p); ndx = (ndx + (consumed ? 0 : 1)) | 0) {
        consumed = 0;
        argc.v = (cptr.ldI32(argc_p) - ndx) | 0;
        argv.v = cptr.add(cptr.ldPtr(argv_p), ndx, 8);

        arg = (origarg = cptr.ldPtro(argv.v, 0, 8));
        /* skip any args intended for deferred options */
        if (cptr.ld1s(arg) != 45)
            continue;
        /* allow second dash if arg name is longer than one character */
        if (cptr.ld1so(arg, 0) == 45 &&
                cptr.ld1so(arg, 1) == 45 &&
                cptr.ld1so(arg, 2) != 0 &&
                (cptr.ld1so(arg, 3) != 0 && cptr.ld1so(arg, 3) != 61 && cptr.ld1so(arg, 3) != 58))
            arg = cptr.add(arg, 1);

        switch (cptr.ld1so(arg, 1)) {
            case 98:
                // --bidshow
                if ((yield* argcheck(argc.v, argv.v, NHC.ARG_BIDSHOW)) == 2) {
                    (yield* opt_terminate());
                    /*NOTREACHED*/
                }
                break;
            case 100:
                if ((yield* argcheck(argc.v, argv.v, NHC.ARG_DEBUG)) == 1) {
                    consume_arg(ndx, argc_p, argv_p), consumed = 1;
                } else if ((yield* argcheck(argc.v, argv.v, NHC.ARG_DUMPENUMS)) == 2) {
                    (yield* opt_terminate());
                } else if ((yield* argcheck(argc.v, argv.v, NHC.ARG_DUMPMONGEN)) == 2) {
                    (yield* opt_terminate());
                    /*NOTREACHED*/
                } else if ((yield* argcheck(argc.v, argv.v, NHC.ARG_DUMPWEIGHTS)) == 2) {
                    (yield* opt_terminate());
                    /*NOTREACHED*/
                } else {
                    oldargc = argc.v;
                    arg = (yield* lopt(
                        arg,
                        (NHC.ArgValRequired | NHC.ArgNamOneLetter | NHC.ArgErrSilent),
                        __s_directory,
                        origarg,
                        argc,
                        argv
                    ));
                    if (!arg)
                        (yield* error(__s_flag_d_must_be_followed_by_a_directory));
                    if (cptr.ld1s(arg) != 101) {
                        cptr.stPtr(hackdir_p, arg);
                        if (oldargc == argc.v)
                            consume_arg(ndx, argc_p, argv_p), consumed = 1;
                        else
                            consume_two_args(ndx, argc_p, argv_p), consumed = 2;
                    }
                }
                break;
            case 104:
            case 63:
                if ((yield* lopt(arg, NHC.ArgValDisallowed, __s_help, origarg, argc, argv)) ||
                        (yield* lopt(
                            arg,
                            (NHC.ArgValDisallowed | NHC.ArgNamOneLetter),
                            __s_dash_query,
                            origarg,
                            argc,
                            argv
                        )))
                    (yield* opt_usage(cptr.ldPtr(hackdir_p)));  /* doesn't return */
                break;
            case 110:
                oldargc = argc.v;
                if (!strcmp(arg, __s_no_nethackrc))
                    arg = (__s_dev_null);
                else
                    arg = (yield* lopt(
                        arg,
                        (NHC.ArgValRequired | NHC.ArgErrComplain),
                        __s_nethackrc$earlyarg,
                        origarg,
                        argc,
                        argv
                    ));
                if (arg) {
                    cptr.stPtro(gc, $instance_globals_c_cmdline_rcfile, (yield* dupstr(arg)));
                    if (oldargc == argc.v)
                        consume_arg(ndx, argc_p, argv_p), consumed = 1;
                    else
                        consume_two_args(ndx, argc_p, argv_p), consumed = 2;
                }
                break;
            case 115:
                if ((yield* argcheck(argc.v, argv.v, NHC.ARG_SHOWPATHS)) == 2) {
                    cptr.st1o(gd, $instance_globals_d_deferred_showpaths, 1);
                    cptr.stPtro(
                        gd,
                        $instance_globals_d_deferred_showpaths_dir,
                        cptr.ldPtr(hackdir_p)
                    );
                    (yield* config_error_done());
                    return;
                }
                /* check for "-s" request to show scores */
                if ((yield* lopt(
                    arg,
                    ((NHC.ArgValDisallowed | NHC.ArgErrComplain) |
                        ((cptr.ld1so(origarg, 1) != 45) ? NHC.ArgNamOneLetter : 0)),
                    __s_scores$earlyarg,
                    origarg,
                    argc,
                    argv
                ))) {
                    /* at this point, argv[0] contains "-scores" or a leading
                       substring of it; prscore() (via scores_only()) expects
                       that to be in argv[1] so we adjust the pointer to make
                       that be the case; if there are any non-early args waiting
                       to be passed along to process_options(), the resulting
                       argv[0] will be one of those rather than the program
                       name but prscore() doesn't care */
                    (yield* scores_only((argc.v + 1) | 0, cptr.add(argv.v, -(1), 8), cptr.ldPtr(hackdir_p)));
                    /*NOTREACHED*/
                }
                break;
            case 117:
                if ((yield* lopt(arg, NHC.ArgValDisallowed, __s_usage, origarg, argc, argv)))
                    (yield* opt_usage(cptr.ldPtr(hackdir_p)));
                break;
            case 118:
                if ((yield* argcheck(argc.v, argv.v, NHC.ARG_VERSION)) == 2) {
                    (yield* opt_terminate());
                    /*NOTREACHED*/
                }
                break;
            case 119:
                arg = (yield* lopt(
                    arg,
                    (NHC.ArgValRequired | NHC.ArgNamOneLetter | NHC.ArgErrComplain),
                    __s_windowtype,
                    origarg,
                    argc,
                    argv
                ));
                if (cptr.ldPtro(gc, $instance_globals_c_cmdline_windowsys))
                    cptr.free(cptr.ldPtro(gc, $instance_globals_c_cmdline_windowsys));
                cptr.stPtro(gc, $instance_globals_c_cmdline_windowsys, arg ? (yield* dupstr(arg)) : null);
                break;
            default:
                break;
        }
    }
    /* empty or "N errors on command line" */
    (yield* config_error_done());
    return;
}

/* for command-line options that perform some immediate action and then
   terminate the program without starting play, like 'nethack --version'
   or 'nethack -s Zelda'; do some cleanup before that termination */
/** C ref: earlyarg.c:366 */
function* opt_terminate() {
    cptr.stI32o(program_state, $sinfo_early_options, 0);
    (yield* config_error_done());  /* free memory allocated by config_error_init() */

    (yield* nh_terminate(0));
    /*NOTREACHED*/
}

/** C ref: earlyarg.c:376 — @param {CPtr<char>} hackdir */
function* opt_usage(hackdir) {
    (yield* chdirx(hackdir, 1));
    ;

    genl_display_file(__s_usagehlp, 1);
    (yield* opt_terminate());
}

/* show the sysconf file name, playground directory, run-time configuration
   file name, dumplog file name if applicable, and some other things */
/** C ref: earlyarg.c:391 — @param {CPtr<char>} dir */
function* after_opt_showpaths(dir) {
    (yield* chdirx(dir, 0));
    (yield* opt_terminate());
    /*NOTREACHED*/
}

/* handle "-s <score options> [character-names]" to show all the entries
   in the high scores file ('record') belonging to particular characters;
   nethack will end after doing so without starting play */
/** C ref: earlyarg.c:406 — @param {CInt} argc @param {CPtr<char *>} argv @param {CPtr<char>} dir */
function* scores_only(argc, argv, dir) {
    /* do this now rather than waiting for final termination, in case there
       is an error summary coming */
    (yield* config_error_done());
    (yield* chdirx(dir, 0));
    cptr.st1o(iflags, $instance_flags_initoptions_noterminate, 1);
    (yield* initoptions());  /* sysconf options affect whether panictrace is enabled */
    cptr.st1o(iflags, $instance_flags_initoptions_noterminate, 0);
    ARGV0.v = cptr.ldPtr(gh);  /* save for possible stack trace */
    panictrace_setsignals(1);
    void whoami();  /* set up default plname[] */
    (yield* prscore(argc, argv));

    (yield* nh_terminate(0));  /* bypass opt_terminate() */
    /*NOTREACHED*/
}

/*
 * Returns:
 *    0 = no match
 *    1 = found and skip past this argument
 *    2 = found and trigger immediate exit
 */
/**
 * C ref: earlyarg.c:450
 * @param {CInt} argc
 * @param {CPtr<char *>} argv
 * @param {*} e_arg
 * @returns {CInt}
 */
function* argcheck(argc, argv, e_arg) {
    let i;
    let idx;
    let match = 0;
    let userea = null;
    let dashdash = __s_empty$earlyarg;

    for (idx = 0; idx < 8; idx++) {
        if (cptr.ldI32o(earlyopts, idx, $sizeof_early_opt) == e_arg) {
            break;
        }
    }
    if (idx >= 8 || argc < 1)
        return 0;

    for (i = 0; i < argc; ++i) {
        if (cptr.ld1so(cptr.ldPtro(argv, i, 8), 0) != 45)
            continue;
        if (cptr.ld1so(cptr.ldPtro(argv, i, 8), 1) == 45) {
            userea = cptr.add(cptr.ldPtro(argv, i, 8), 2);
            dashdash = __s_dash;
        } else {
            userea = cptr.add(cptr.ldPtro(argv, i, 8), 1);
        }
        match = (yield* match_optname(
            userea,
            cptr.ldPtro2(earlyopts, idx, $sizeof_early_opt, $early_opt_name),
            cptr.ldI32o2(earlyopts, idx, $sizeof_early_opt, $early_opt_minlength),
            cptr.ld1so2(earlyopts, idx, $sizeof_early_opt, $early_opt_valallowed)
        ));
        if (match)
            break;
    }

    if (match) {
        let extended_opt = cptr.strchr(userea, 58);

        if (!extended_opt)
            extended_opt = cptr.strchr(userea, 61);
        switch (e_arg) {
            case NHC.ARG_DEBUG:
                if (extended_opt) {
                    let cpy_extended_opt;

                    cpy_extended_opt = (yield* dupstr(extended_opt));
                    (yield* debug_fields(cptr.add(cpy_extended_opt, 1)));
                    cptr.free(cpy_extended_opt);
                }
                return 1;
            case NHC.ARG_VERSION:
                {
                    let insert_into_pastebuf = 0;

                    if (extended_opt) {
                        extended_opt = cptr.add(extended_opt, 1);
                        /* Deprecated in favor of "copy" - remove no later
                           than  next major version */
                        if ((yield* match_optname(extended_opt, __s_paste, 5, 0))) {
                            insert_into_pastebuf = 1;
                        } else if ((yield* match_optname(extended_opt, __s_copy, 4, 0))) {
                            insert_into_pastebuf = 1;
                        } else if ((yield* match_optname(extended_opt, __s_dump, 4, 0))) {
                            /* version number plus enabled features and sanity
                               values that the program compares against the same
                               thing recorded in save and bones files to check
                               whether they're being used compatibly */
                            (yield* dump_version_info());
                            return 2;  /* done */
                        } else if (!(yield* match_optname(extended_opt, __s_show, 4, 0))) {
                            (yield* raw_printf$pline(__s_sversion_can_only_be_extended_with, dashdash, dashdash));
                            /* exit after we've reported bad command line argument */
                            return 2;
                        }
                    }
                    (yield* early_version_info(insert_into_pastebuf));
                    return 2;
                }
            case NHC.ARG_SHOWPATHS:
                return 2;
            case NHC.ARG_DUMPENUMS:
                (yield* dump_enums());
                return 2;
            case NHC.ARG_DUMPGLYPHIDS:
                (yield* dump_glyphids());
                return 2;
            case NHC.ARG_DUMPMONGEN:
                (yield* dump_mongen());
                return 2;
            case NHC.ARG_DUMPWEIGHTS:
                (yield* dump_weights());
                return 2;
            case NHC.ARG_BIDSHOW:
                (yield* crashreport_bidshow());
                return 2;
            default:
                break;
        }
    }
    ;
    return 0;
}

/*
 * These are internal controls to aid developers with
 * testing and debugging particular aspects of the code.
 * They are not player options and the only place they
 * are documented is right here. No gameplay is altered.
 *
 * test             - test whether this parser is working
 * ttystatus        - TTY:
 * immediateflips   - WIN32: turn off display performance
 *                    optimization so that display output
 *                    can be debugged without buffering.
 * fuzzer           - enable fuzzer without debugger intervention.
 */
/** C ref: earlyarg.c:576 — @param {CPtr<char>} opts */
function* debug_fields(opts) {
    let op;
    let negated = 0;

    while ((op = cptr.strchr(opts, 44)) !== null) {
        cptr.st1(cptr.postinc(() => op, (v) => { op = v; }), 0);
        /* recurse */
        (yield* debug_fields(op));
    }
    if (cptr.strlen(opts) > 128n)
        return;

    /* strip leading and trailing white space */
    while (isspace(uchar(cptr.ld1s(opts))))
        opts = cptr.add(opts, 1);
    op = eos(opts);
    while (cptr.cmp(cptr.predec(() => op, (v) => { op = v; }), opts) >= 0 &&
            isspace(uchar(cptr.ld1s(op))))
        cptr.st1(op, 0);

    if (!cptr.ld1s(opts)) {
        /* empty */
        return;
    }
    while ((cptr.ld1s(opts) == 33) || !(yield* strncmpi(opts, __s_no$earlyarg, 2))) {
        if (cptr.ld1s(opts) == 33)
            opts = cptr.add(opts, 1);
        else
            opts = cptr.add(opts, 2);
        negated = schar((!negated));
    }
    if ((yield* match_optname(opts, __s_test, 4, 0)))
        cptr.st1o(iflags, $instance_flags_debug, schar((negated ? 0 : 1)));
    if ((yield* match_optname(opts, __s_ttystatus, 9, 0)))
        cptr.st1o(iflags, $instance_flags_debug + $debug_flags_ttystatus, schar((negated ? 0 : 1)));
    if ((yield* match_optname(opts, __s_fuzzer, 4, 0)))
        cptr.st1o(iflags, $instance_flags_fuzzerpending, 1);
    return;
}

