/* ask user if they want a tutorial, except if tutorial boolean option has
   been set in config - either on or off - in which case just obey that
   setting without asking */
/** C ref: options.c:430 @returns {CInt} */
function* ask_do_tutorial() {
    let dotut = cptr.ld1so(flags, $flag_tutorial);

    if (!cptr.ld1so(cptr.decay(opt_set_in_config), NHC.opt_tutorial, 1)) {
        let win;
        let sel = cptr.box(0);
        let any = cptr.alloc(8);
        let buf = new Uint8Array(256);
        let rc;
        let norc;
        let n;
        let pass = 0;

        rc = nh_basename(get_configfile(), 1);
        norc = schar((!strcmp(get_configfile(), __s_dev_null$options)));
        nh_snprintf(
            __s_ask_do_tutorial,
            447,
            cptr.decay(buf),
            256n,
            __s_put_options_tutorial_in_s_to_skip_this,
            (rc && cptr.ld1s(rc) && !norc) ? rc : __s_your_configuration_file
        );
        do {
            win = (yield* Y.icall(create_nhwindow()(NHM.NHW_MENU)));
            (yield* Y.icall(start_menu()(win, 0n)));
            cptr.memcpy(any, cptr.add(cg, $const_globals_zeroany), 8);
            cptr.st1(any, 121);
            (yield* add_menu(
                win,
                nul_glyphinfo.v,
                any,
                cptr.ld1s(any),
                0,
                NHM.ATR_NONE,
                NHM.NO_COLOR,
                __s_yes_do_a_tutorial,
                NHM.MENU_ITEMFLAGS_NONE
            ));
            cptr.st1(any, 110);
            (yield* add_menu(
                win,
                nul_glyphinfo.v,
                any,
                cptr.ld1s(any),
                0,
                NHM.ATR_NONE,
                NHM.NO_COLOR,
                __s_no_just_start_play,
                NHM.MENU_ITEMFLAGS_NONE
            ));

            (yield* add_menu_str(win, __s_empty$options));
            (yield* add_menu_str(win, cptr.decay(buf)));
            if (pass++)
                (yield* add_menu_str(win, __s_please_choose_y_or_n));

            (yield* Y.icall(end_menu()(win, __s_do_you_want_a_tutorial)));

            n = (yield* select_menu(win, NHM.PICK_ONE, sel));
            (yield* Y.icall(destroy_nhwindow()(win)));
        } while (!n);
        if (n > 0) {
            dotut = schar((cptr.ld1so(sel.v, 0, $sizeof_menu_item) == 121));
            cptr.free(sel.v);
        } else {
            dotut = 0;
        }
    }
    return dotut;
}

