/*
 *    General boolean option handler
 *    (Use optidx to reference the specific option)
 */

/**
 * C ref: options.c:5192
 * @param {CInt} optidx
 * @param {CInt} req
 * @param {CInt} negated
 * @param {CPtr<char>} opts
 * @param {CPtr<char>} op
 * @returns {CInt}
 */
function* optfn_boolean(optidx, req, negated, opts, op) {
    if (req == NHC.do_init) {
        return NHC.optn_ok;
    }
    if (req == NHC.do_set) {
        let nosexchange = 0;
        let ln = 0;

        if (!cptr.ldPtro2(allopt, optidx, $sizeof_allopt_t, $allopt_t_addr))
            return NHC.optn_ok;  /* silent retreat */

        /* option that must come from config file? */
        if (!cptr.ld1so(go, $instance_globals_o_opt_initial) &&
                (cptr.ldI32o2(allopt, optidx, $sizeof_allopt_t, $allopt_t_setwhere) ==
                    NHC.set_in_config))
            return NHC.optn_err;

        /* options that must NOT come from config file */
        if (cptr.ld1so(go, $instance_globals_o_opt_initial) &&
                cptr.ldI32o2(allopt, optidx, $sizeof_allopt_t, $allopt_t_setwhere) ==
                    NHC.set_wiznofuz)
            return NHC.optn_err;

        op = (yield* string_for_opt(opts, 1));
        if (!cptr.eq(op, cptr.decay(empty_optstr))) {
            if (negated) {
                (yield* config_error_add(
                    __s_negated_boolean_s_should_not_have_a,
                    cptr.ldPtro(allopt, optidx, $sizeof_allopt_t)
                ));
                return NHC.optn_silenterr;
            }
            /* length is greater than 0 or we wouldn't have gotten here */
            ln = Number(BigInt.asIntN(32, cptr.strlen(op)));
            if (!(yield* strncmpi(op, __s_true$options, ln)) ||
                    !(yield* strncmpi(op, __s_yes, ln)) ||
                    !(yield* strncmpi((op), (__s_on$options), -1)) ||
                    (digit(cptr.ld1s(op)) && atoi(op) == 1)) {
                negated = 0;
            } else if (!(yield* strncmpi(op, __s_false$options, ln)) ||
                    !(yield* strncmpi(op, __s_no$options, ln)) ||
                    !(yield* strncmpi((op), (__s_off$options), -1)) ||
                    (digit(cptr.ld1s(op)) && atoi(op) == 0)) {
                negated = 1;
            } else if (!cptr.ldI32o2(allopt, optidx, $sizeof_allopt_t, $allopt_t_valok)) {
                (yield* config_error_add(__s_s_is_not_valid_for_a_boolean, opts));
                return NHC.optn_silenterr;
            }
        }
        if (cptr.ld1so(iflags, $instance_flags_debug_fuzzer) &&
                !cptr.ld1so(go, $instance_globals_o_opt_initial)) {
            /* don't randomly toggle this/these */
            if ((optidx == NHC.opt_silent) || (optidx == NHC.opt_perm_invent))
                return NHC.optn_ok;
        }
        /* Before the change */
        switch (optidx) {
            case NHC.opt_female:
                if (!(yield* strncmpi(opts, __s_female$options, ((ln) > 3 ? (ln) : 3)))) {
                    if (!cptr.ld1so(go, $instance_globals_o_opt_initial) &&
                            cptr.ld1so(flags, $flag_female) == negated) {
                        nosexchange = 1;
                    } else {
                        cptr.stI32o(
                            flags,
                            $flag_initgend,
                            cptr.st1o(flags, $flag_female, schar((!negated)))
                        );
                        return NHC.optn_ok;
                    }
                }
                if (!(yield* strncmpi(opts, __s_male$options, ((ln) > 3 ? (ln) : 3)))) {
                    if (!cptr.ld1so(go, $instance_globals_o_opt_initial) &&
                            cptr.ld1so(flags, $flag_female) != negated) {
                        nosexchange = 1;
                    } else {
                        cptr.stI32o(flags, $flag_initgend, cptr.st1o(flags, $flag_female, negated));
                        return NHC.optn_ok;
                    }
                }
                break;
            case NHC.opt_perm_invent:
                if (!negated &&
                        !cptr.ld1so(go, $instance_globals_o_opt_initial) &&
                        !can_set_perm_invent())
                    return NHC.optn_silenterr;
                break;
            default:
                break;
        }
        /* this dates from when 'O' prompted for a line of options text
           rather than use a menu to control access to which options can
           be modified during play; it was possible to attempt to use
           'O' to specify female or negate male when playing as male or
           to specify male or negate female when playing as female;
           options processing rejects that for !opt_initial; not possible
           now but kept in case someone brings the old 'O' behavior back */
        if (nosexchange) {
            /* can't arbitrarily change sex after game has started;
               magic (amulet or polymorph) is required for that */
            (yield* config_error_add(__s_s_is_not_anatomically_possible, opts));
            return NHC.optn_silenterr;
        }

        cptr.st1(
            (cptr.ldPtro2(allopt, optidx, $sizeof_allopt_t, $allopt_t_addr)),
            schar((!negated))
        );  /* <==== SET IT HERE */

        /* After the change */
        switch (optidx) {
            case NHC.opt_pauper:
                /* pauper implies nudist */
                cptr.st1o(
                    u,
                    $you_uroleplay + $u_roleplay_nudist,
                    cptr.ld1so(u, $you_uroleplay + $u_roleplay_pauper)
                );
                break;
            case NHC.opt_ascii_map:
                cptr.st1o(iflags, $instance_flags_wc_tiled_map, negated);
                break;
            case NHC.opt_tiled_map:
                cptr.st1o(iflags, $instance_flags_wc_ascii_map, negated);
                break;
            case NHC.opt_hilite_pet:
                if ((cptr.ldI32o(windowprocs, $window_procs_wp_id) == NHC.wp_tty) ||
                        (cptr.ldI32o(windowprocs, $window_procs_wp_id) == NHC.wp_curses)) {
                    /* if we're enabling hilite_pet and petattr isn't set,
                       set it to Inverse; if we're disabling, leave petattr
                       alone so that re-enabling will get current value back
                     */
                    if (cptr.ld1so(iflags, $instance_flags_wc_hilite_pet) &&
                            !cptr.ldI32o(iflags, $instance_flags_wc2_petattr))
                        cptr.stI32o(iflags, $instance_flags_wc2_petattr, NHM.ATR_INVERSE);
                }
                cptr.st1o(go, $instance_globals_o_opt_need_redraw, 1);
                break;
            case NHC.opt_idlecheckpoint:
                (yield* pline(__s_there_is_no_underlying_support_for));
                cptr.st1o(iflags, $instance_flags_idlecheckpoint, 0);
                give_opt_msg = 0;
                break;
            default:
                break;
        }

        /* only do processing below if setting with doset() */

        if (cptr.ld1so(go, $instance_globals_o_opt_initial))
            return NHC.optn_ok;

        switch (optidx) {
            case NHC.opt_terrainstatus:
                classify_terrain();  /* bring iflags.terrain_typ up to date */
                // @FallThrough
                ;
            case NHC.opt_weaponstatus:
            case NHC.opt_armorstatus:
                if (!wc2_supported(cptr.ldPtro(allopt, optidx, $sizeof_allopt_t))) {
                    /* not actually an error */
                    (yield* config_error_add(
                        __s_s_is_not_supported,
                        cptr.ldPtro(allopt, optidx, $sizeof_allopt_t)
                    ));
                    return NHC.optn_ok;
                }
                // @FallThrough
                ;
            case NHC.opt_showscore:
            case NHC.opt_showvers:
            case NHC.opt_showexp:
            case NHC.opt_time:
                if (((cptr.ldU64o(windowprocs, $window_procs_wincap2) & 136n) != 0n))
                    (yield* status_initialize(1));
                cptr.st1(disp, 1);
                break;
            case NHC.opt_fixinv:
            case NHC.opt_price_quotes:
            case NHC.opt_sortpack:
            case NHC.opt_implicit_uncursed:
            case NHC.opt_wizweight:
                if (!cptr.ld1so(flags, $flag_invlet_constant))
                    reassign();
                (yield* update_inventory());
                break;
            case NHC.opt_lit_corridor:
            case NHC.opt_dark_room:
                /*
                 * All corridor squares seen via night vision or
                 * candles & lamps change.  Update them by calling
                 * newsym() on them.  Don't do this if we are
                 * initializing the options --- the vision system
                 * isn't set up yet.
                 */
                (yield* vision_recalc(2));  /* shut down vision */
                cptr.st1o(gv, $instance_globals_v_vision_full_recalc, 1);  /* delayed recalc */
                if (cptr.ld1so(iflags, $instance_flags_wc_color))
                    cptr.st1o(go, $instance_globals_o_opt_need_redraw, 1);  /* darkroom refresh */
                break;
            case NHC.opt_wizmgender:
            case NHC.opt_showrace:
            case NHC.opt_use_inverse:
            case NHC.opt_hilite_pile:
            case NHC.opt_perm_invent:
            case NHC.opt_ascii_map:
            case NHC.opt_tiled_map:
                cptr.st1o(go, $instance_globals_o_opt_need_redraw, 1);
                cptr.st1o(go, $instance_globals_o_opt_need_glyph_reset, 1);
                break;
            case NHC.opt_hitpointbar:
                if (((cptr.ldU64o(windowprocs, $window_procs_wincap2) & 136n) != 0n)) {
                    /* [is reassessment really needed here?] */
                    (yield* status_initialize(1));
                    cptr.st1o(go, $instance_globals_o_opt_need_redraw, 1);
                }
                break;
            case NHC.opt_color:
                cptr.st1o(go, $instance_globals_o_opt_need_redraw, 1);
                cptr.st1o(go, $instance_globals_o_opt_need_glyph_reset, 1);
                break;
            case NHC.opt_customcolors:
                cptr.st1o(go, $instance_globals_o_opt_reset_customcolors, 1);
                break;
            case NHC.opt_customsymbols:
                cptr.st1o(go, $instance_globals_o_opt_reset_customsymbols, 1);
                break;
            case NHC.opt_menucolors:
            case NHC.opt_guicolor:
                (yield* update_inventory());
                cptr.st1o(go, $instance_globals_o_opt_need_promptstyle, 1);
                break;
            case NHC.opt_mention_decor:
                cptr.st1o(iflags, $instance_flags_prev_decor, NHC.STONE);
                break;
            case NHC.opt_rest_on_space:
                (yield* update_rest_on_space());
                break;
            case NHC.opt_accessiblemsg:
                cptr.stI16o(
                    a11y,
                    $accessibility_data_msg_loc,
                    cptr.stI16o(a11y, $accessibility_data_msg_loc + $nhcoord_y, 0)
                );
                break;
            default:
                break;
        }

        /* boolean value has been toggled but some option changes can
           still be pending at this point (mainly for opt_need_redraw);
           give the toggled message now regardless */
        if (give_opt_msg)
            (yield* pline(
                __s_s_option_toggled_s,
                cptr.ldPtro(allopt, optidx, $sizeof_allopt_t),
                !negated ? __s_on$options : __s_off$options
            ));

        return NHC.optn_ok;
    }
    if (req == NHC.get_val || req == NHC.get_cnf_val) {
        cptr.st1o(opts, 0, 0);
        return NHC.optn_ok;
    }
    return NHC.optn_ok;
}

