/** C ref: u_init.c:575 — @param {CInt} obj @param {CInt} override_pauper */
function* knows_object(obj, override_pauper) {
    if (cptr.ld1so(u, $you_uroleplay + $u_roleplay_pauper) && !override_pauper)
        return;
    /* mark as known, but not yet encountered */
    (yield* discover_object(obj, 1, 0, 0));
}

/* Know ordinary (non-magical) objects of a certain class,
   like all gems except the loadstone and luckstone. */
/** C ref: u_init.c:586 — @param {CInt} sym */
function* knows_class(sym) {
    let odummy = cptr.alloc(216);
    let o;
    let ct;

    if (cptr.ld1so(u, $you_uroleplay + $u_roleplay_pauper))
        return;

    cptr.memcpy(odummy, cg, 216);
    cptr.st1o(odummy, $obj_oclass, sym);
    o = odummy;  /* for use in various obj.h macros */

    /*
     * Note:  the exceptions here can be bypassed if necessary by
     *        calling knows_object() directly.  So an elven ranger,
     *        for example, knows all elven weapons despite the bow,
     *        arrow, and spear limitation below.
     */

    for (
        ct = cptr.ldI32o2(svb, uchar(sym), 4, $instance_globals_saved_b_bases);
        ct < cptr.ldI32o2(svb, (uchar(sym) + 1) | 0, 4, $instance_globals_saved_b_bases);
        ct++
    ) {
        /* not flagged as magic but shouldn't be pre-discovered
           (small shields look the same as two types of magical shield;
           cornuthaum / dunce cap look the same as each other) */
        if (ct == NHC.CORNUTHAUM || ct == NHC.DUNCE_CAP || ct == NHC.SMALL_SHIELD)
            continue;
        if (sym == NHC.WEAPON_CLASS) {
            cptr.stI16o(odummy, $obj_otyp, i16(ct));  /* update 'o' */
            /* arbitrary: only knights and samurai recognize polearms */
            if ((!(cptr.ldI16o(gu, $instance_globals_u_urole + $Role_mnum) == NHC.PM_KNIGHT) &&
                !(cptr.ldI16o(gu, $instance_globals_u_urole + $Role_mnum) == NHC.PM_SAMURAI)) &&
                    is_pole(o))
                continue;
            /* rangers know all launchers (bows, &c), ammo (arrows, &c),
               and spears regardless of race/species, but not other weapons */
            if ((cptr.ldI16o(gu, $instance_globals_u_urole + $Role_mnum) == NHC.PM_RANGER) &&
                    (!is_launcher(o) && !is_ammo(o) && !is_spear(o)))
                continue;
            /* rogues know daggers, regardless of racial variations */
            if ((cptr.ldI16o(gu, $instance_globals_u_urole + $Role_mnum) == NHC.PM_ROGUE) &&
                    (cptr.ld1so2(
                        objects,
                        cptr.ldI16o(o, $obj_otyp),
                        $sizeof_objclass,
                        $objclass_oc_subtyp
                    ) !=
                        NHC.P_DAGGER))
                continue;
        }

        if (cptr.ld1so2(objects, ct, $sizeof_objclass, $objclass_oc_class) == sym &&
                !(cptr.ldI32o2(objects, ct, $sizeof_objclass, $objclass_oc_magic) & 1))
            (yield* knows_object(ct, 0));
    }
}

/* role-specific initializations, mostly inventory

   other things may be initialised here, but the function might run more than
   once, so any non-inventory initialisations should be nonrandom and
   idempotent (i.e. doing them twice is OK) */
const __static_u_init_role_M_spell = cptr.alloc(3 * 8);
cptr.stPtro(__static_u_init_role_M_spell, 0, Healing_book);
cptr.stPtro(__static_u_init_role_M_spell, 8, Protection_book);
cptr.stPtro(__static_u_init_role_M_spell, 16, Confuse_monster_book); /** C ref: u_init.c:694 — struct trobj *[3] (function-static) */

/** C ref: u_init.c:637 */
function* u_init_role() {
    let i;

    /* the program used to check moves<=1 && invent==NULL do decide whether
       a new game has started, but due to the 'pauper' option/conduct, can't
       rely on invent becoming non-Null anymore; instead, initialize moves
       to 0 instead of 1, then set it to 1 here, where invent init occurs */
    cptr.stI64o(svm, $instance_globals_saved_m_moves, 1n);

    switch (Role_switch()) {
        case NHC.PM_ARCHEOLOGIST:
            (yield* ini_inv(Archeologist));
            if (!rn2(10))
                (yield* ini_inv(Tinopener));
            else if (!rn2(4))
                (yield* ini_inv(Lamp));
            else if (!rn2(5))
                (yield* ini_inv(Magicmarker));
            (yield* knows_object(NHC.SACK, 0));
            (yield* knows_object(NHC.TOUCHSTONE, 0));
            break;
        case NHC.PM_BARBARIAN:
            if (rn2(100) >= 50) {
                (yield* ini_inv(Barbarian_0));
            } else {
                (yield* ini_inv(Barbarian_1));
            }
            if (!rn2(6))
                (yield* ini_inv(Lamp));
            (yield* knows_class(NHC.WEAPON_CLASS));  /* excluding polearms */
            (yield* knows_class(NHC.ARMOR_CLASS));
            break;
        case NHC.PM_CAVE_DWELLER:
            (yield* ini_inv(Cave_man));
            break;
        case NHC.PM_HEALER:
            cptr.stI64o(u, $you_umoney0, BigInt(((rn2(1000) + 1001) | 0)));
            (yield* ini_inv(Healer));
            if (!rn2(25))
                (yield* ini_inv(Lamp));
            (yield* knows_object(NHC.POT_FULL_HEALING, 0));
            break;
        case NHC.PM_KNIGHT:
            (yield* ini_inv(Knight));
            (yield* knows_class(NHC.WEAPON_CLASS));  /* all weapons */
            (yield* knows_class(NHC.ARMOR_CLASS));
            /* give knights chess-like mobility--idea from wooledge@..cwru.edu */
            cptr.stI64o2(
                u,
                NHC.JUMPING,
                $sizeof_prop,
                $you_uprops + $prop_intrinsic,
                cptr.ldI64o2(u, NHC.JUMPING, $sizeof_prop, $you_uprops + $prop_intrinsic) |
                    67108864n
            );
            break;
        case NHC.PM_MONK:
            {

                (yield* ini_inv(Monk));
                (yield* ini_inv(cptr.ldPtro(__static_u_init_role_M_spell, (rn2(90) / 30) | 0, 8)));  /* [0..2] */
                if (!rn2(4))
                    (yield* ini_inv(Magicmarker));
                else if (!rn2(10))
                    (yield* ini_inv(Lamp));
                (yield* knows_class(NHC.ARMOR_CLASS));
                /* sufficiently martial-arts oriented item to ignore language issue */
                (yield* knows_object(NHC.SHURIKEN, 0));
                break;
            }
        case NHC.PM_CLERIC:
            (yield* ini_inv(Priest));
            if (!rn2(5))
                (yield* ini_inv(Magicmarker));
            else if (!rn2(10))
                (yield* ini_inv(Lamp));
            (yield* knows_object(NHC.POT_WATER, 1));  /* override pauper */
            /* KMH, conduct --
             * Some may claim that this isn't agnostic, since they
             * are literally "priests" and they have holy water.
             * But we don't count it as such.  Purists can always
             * avoid playing priests and/or confirm another player's
             * role in their YAAP.
             */
            break;
        case NHC.PM_RANGER:
            (yield* ini_inv(Ranger));
            (yield* knows_class(NHC.WEAPON_CLASS));  /* bows, arrows, spears only */
            break;
        case NHC.PM_ROGUE:
            cptr.stI64o(u, $you_umoney0, 0n);
            (yield* ini_inv(Rogue));
            if (!rn2(5))
                (yield* ini_inv(Blindfold));
            (yield* knows_object(NHC.SACK, 0));
            (yield* knows_class(NHC.WEAPON_CLASS));  /* daggers only */
            break;
        case NHC.PM_SAMURAI:
            (yield* ini_inv(Samurai));
            if (!rn2(5))
                (yield* ini_inv(Blindfold));
            (yield* knows_class(NHC.WEAPON_CLASS));  /* all weapons */
            (yield* knows_class(NHC.ARMOR_CLASS));
            /* in order to assist non-Japanese speakers, pre-discover items
               that switch to Japanese names when playing as a Samurai */
            for (i = NHC.MAXOCLASSES; i < NHC.NUM_OBJECTS; ++i) {
                if ((cptr.ldI32o2(objects, i, $sizeof_objclass, $objclass_oc_magic) & 1))
                    continue;
                if (Japanese_item_name(i, null))
                    /* we don't override pauper here because that would give
                       samarai an advantage of knowing several items in advance */
                    (yield* knows_object(i, 0));
            }
            break;
        case NHC.PM_TOURIST:
            cptr.stI64o(u, $you_umoney0, BigInt(rnd(1000)));
            (yield* ini_inv(Tourist));
            if (!rn2(25))
                (yield* ini_inv(Tinopener));
            else if (!rn2(25))
                (yield* ini_inv(Leash));
            else if (!rn2(25))
                (yield* ini_inv(Towel));
            else if (!rn2(20))
                (yield* ini_inv(Magicmarker));
            break;
        case NHC.PM_VALKYRIE:
            (yield* ini_inv(Valkyrie));
            if (!rn2(6))
                (yield* ini_inv(Lamp));
            (yield* knows_class(NHC.WEAPON_CLASS));  /* excludes polearms */
            (yield* knows_class(NHC.ARMOR_CLASS));
            break;
        case NHC.PM_WIZARD:
            (yield* ini_inv(Wizard));
            if (!rn2(5))
                (yield* ini_inv(Blindfold));
            break;
        default:
            break;
    }

    cptr.stI16o(gn, $instance_globals_n_nocreate, NHC.STRANGE_OBJECT);
    cptr.stI16o(gn, $instance_globals_n_nocreate2, NHC.STRANGE_OBJECT);
    cptr.stI16o(gn, $instance_globals_n_nocreate3, NHC.STRANGE_OBJECT);
    cptr.stI16o(gn, $instance_globals_n_nocreate4, NHC.STRANGE_OBJECT);
}

