/** C ref: spell.c:468 — @param {CPtr<struct obj>} spellbook @returns {CInt} */
function* study_book(spellbook) {
    let booktype = cptr.ldI16o(spellbook, $obj_otyp);
    let i;
    let confused = schar((HConfusion() != 0n));
    let too_hard = 0;

    /* attempting to read dull book may make hero fall asleep */
    if (!confused && !Sleep_resistance() && (yield* objdescr_is(spellbook, __s_dull$spell))) {
        let eyes;
        let dullbook = (rnd(25) - (acurr(NHC.A_WIS))) | 0;

        /* adjust chance if hero stayed awake, got interrupted, retries */
        if (cptr.ld1so(svc, $context_info_spbook + $book_info_delay) &&
                cptr.eq(spellbook, cptr.ldPtro(svc, $context_info_spbook)))
            dullbook = (dullbook -
                    rnd(cptr.ld1so2(objects, booktype, $sizeof_objclass, $objclass_oc_oc2))) | 0;

        if (dullbook > 0) {
            eyes = (yield* body_part(NHC.EYE));
            if (eyecount(cptr.ldPtro(gy, $instance_globals_y_youmonst + $monst_data)) > 1)
                eyes = (yield* makeplural(eyes));
            (yield* pline(__s_this_book_is_so_dull_that_you_can_t, eyes));
            dullbook = (dullbook +
                    rnd(Math.imul(
                        2,
                        cptr.ld1so2(objects, booktype, $sizeof_objclass, $objclass_oc_oc2)
                    ))) | 0;
            (yield* fall_asleep(-dullbook, 1));
            return 1;
        }
    }

    if (cptr.ld1so(svc, $context_info_spbook + $book_info_delay) &&
            !confused &&
            cptr.eq(spellbook, cptr.ldPtro(svc, $context_info_spbook)) &&
            booktype != NHC.SPE_BLANK_PAPER) {
        (yield* You(
            __s_continue_your_efforts_to_s,
            (booktype == NHC.SPE_NOVEL) ? __s_read_the_novel : __s_memorize_the_spell
        ));
    } else {
        /* KMH -- Simplified this code */
        if (booktype == NHC.SPE_BLANK_PAPER) {
            (yield* pline(__s_this_spellbook_is_all_blank));
            (yield* discover_object((booktype), 1, 1, 1));
            return 1;
        }

        /* 3.6 tribute */
        if (booktype == NHC.SPE_NOVEL) {
            /* Obtain current Terry Pratchett book title */
            let tribtitle = noveltitle(cptr.add(spellbook, $obj_corpsenm));

            if ((yield* read_tribute(__s_books, tribtitle, 0, null, 0, cptr.ldI32o(spellbook, $obj_o_id)))) {
                if (!((cptr.stI64o(
                    u,
                    $you_uconduct + $u_conduct_literate,
                    cptr.ldI64o(u, $you_uconduct + $u_conduct_literate) + 1n
                )) - (1n)))
                    (yield* livelog_printf(32n, __s_became_literate_by_reading_s$spell, tribtitle));

                (yield* check_unpaid(spellbook));
                (yield* discover_object((booktype), 1, 1, 1));
                if (!(cptr.ldI32o(u, $you_uevent + $u_event_read_tribute) & 1)) {
                    (yield* record_achievement(NHC.ACH_NOVL));
                    /* give bonus of 20 xp and 4*20+0 pts */
                    (yield* more_experienced(20, 0));
                    (yield* newexplevel());
                    cptr.stI32o(u, $you_uevent + $u_event_read_tribute, 1);  /* only once */
                }
            }
            return 1;
        }

        switch (cptr.ld1so2(objects, booktype, $sizeof_objclass, $objclass_oc_oc2)) {
            case 1:
            case 2:
                cptr.st1o(
                    svc,
                    $context_info_spbook + $book_info_delay,
                    schar((-cptr.ld1so2(objects, booktype, $sizeof_objclass, $objclass_oc_delay)))
                );
                break;
            case 3:
            case 4:
                cptr.st1o(
                    svc,
                    $context_info_spbook + $book_info_delay,
                    schar(Math.imul(
                        -((cptr.ld1so2(objects, booktype, $sizeof_objclass, $objclass_oc_oc2) - 1) |
                            0),
                        cptr.ld1so2(objects, booktype, $sizeof_objclass, $objclass_oc_delay)
                    ))
                );
                break;
            case 5:
            case 6:
                cptr.st1o(
                    svc,
                    $context_info_spbook + $book_info_delay,
                    schar(Math.imul(
                        -cptr.ld1so2(objects, booktype, $sizeof_objclass, $objclass_oc_oc2),
                        cptr.ld1so2(objects, booktype, $sizeof_objclass, $objclass_oc_delay)
                    ))
                );
                break;
            case 7:
                cptr.st1o(
                    svc,
                    $context_info_spbook + $book_info_delay,
                    schar(Math.imul(
                        -8,
                        cptr.ld1so2(objects, booktype, $sizeof_objclass, $objclass_oc_delay)
                    ))
                );
                break;
            default:
                (yield* impossible$pline(
                    __s_unknown_spellbook_level_d_book_d,
                    cptr.ld1so2(objects, booktype, $sizeof_objclass, $objclass_oc_oc2),
                    booktype
                ));
                return 0;
        }

        /* check to see if we already know it and want to refresh our memory */
        for (i = 0; i < NHC.MAXSPELL; i++)
            if (cptr.ldI16o(svs, i, $sizeof_spell) == booktype ||
                    cptr.ldI16o(svs, i, $sizeof_spell) == NHM.NO_SPELL)
                break;
        if (cptr.ldI16o(svs, i, $sizeof_spell) == booktype &&
                cptr.ldI32o2(svs, i, $sizeof_spell, $spell_sp_know) > 2000) {
            (yield* You(
                __s_know_s_quite_well_already,
                (cptr.ldPtro(
                    obj_descr,
                    cptr.ldI16((cptr.add(objects, booktype, $sizeof_objclass))),
                    $sizeof_objdescr
                ))
            ));
            /* hero has just been told what spell this book is for; it may
               have been undiscovered if spell was learned via divine gift */
            (yield* discover_object((booktype), 1, 1, 1));
            if ((yield* yn_function(__s_refresh_your_memory_anyway, cptr.decay(ynchars), 110, 1)) == 110)
                return 0;
        }

        /* Books are often wiser than their readers (Rus.) */
        cptr.stI32o(spellbook, $obj_in_use, 1);
        if (!(cptr.ldI32o(spellbook, $obj_blessed) & 1) &&
                cptr.ldI16o(spellbook, $obj_otyp) != NHC.SPE_BOOK_OF_THE_DEAD) {
            if ((cptr.ldI32o(spellbook, $obj_cursed) & 1)) {
                too_hard = 1;
            } else {
                /* uncursed - chance to fail */
                let read_ability = ((acurr(NHC.A_INT)) +
                        4 +
                        ((cptr.ldI32o(u, $you_ulevel) / 2) | 0) -
                        Math.imul(
                            2,
                            cptr.ld1so2(objects, booktype, $sizeof_objclass, $objclass_oc_oc2)
                        ) +
                        ((ublindf.v && cptr.ldI16o(ublindf.v, $obj_otyp) == NHC.LENSES)
                            ? 2
                            : 0)) | 0;

                /* only wizards know if a spell is too difficult */
                if ((cptr.ldI16o(gu, $instance_globals_u_urole + $Role_mnum) == NHC.PM_WIZARD) &&
                        read_ability < 20 &&
                        !confused) {
                    let qbuf = new Uint8Array(128);

                    void cptr.sprintf(
                        cptr.decay(qbuf),
                        __s_this_spellbook_is_sdifficult_to,
                        (read_ability < 12 ? __s_very$spell : __s_empty$spell)
                    );
                    if ((yield* yn_function(cptr.decay(qbuf), cptr.decay(ynchars), 110, 1)) != 121) {
                        cptr.stI32o(spellbook, $obj_in_use, 0);
                        return 1;
                    }
                }
                /* its up to random luck now */
                if (rnd(20) > read_ability) {
                    too_hard = 1;
                }
            }
        }

        if (too_hard) {
            let gone = (yield* cursed_book(spellbook));

            nomul(cptr.ld1so(svc, $context_info_spbook + $book_info_delay));  /* study time */
            cptr.stPtro(gm, $instance_globals_m_multi_reason, __s_reading_a_book);
            cptr.stPtro(gn, $instance_globals_n_nomovemsg, null);
            cptr.st1o(svc, $context_info_spbook + $book_info_delay, 0);
            if (gone || !rn2(3)) {
                if (!gone)
                    (yield* pline_The(__s_spellbook_crumbles_to_dust));
                (yield* trycall(spellbook));
                (yield* useup(spellbook));
            } else
                cptr.stI32o(spellbook, $obj_in_use, 0);
            return 1;
        } else if (confused) {
            if (!(yield* confused_book(spellbook))) {
                cptr.stI32o(spellbook, $obj_in_use, 0);
            }
            nomul(cptr.ld1so(svc, $context_info_spbook + $book_info_delay));
            cptr.stPtro(gm, $instance_globals_m_multi_reason, __s_reading_a_book);
            cptr.stPtro(gn, $instance_globals_n_nomovemsg, null);
            cptr.st1o(svc, $context_info_spbook + $book_info_delay, 0);
            return 1;
        }
        cptr.stI32o(spellbook, $obj_in_use, 0);

        (yield* You(
            __s_begin_to_s_the_runes,
            cptr.ldI16o(spellbook, $obj_otyp) == NHC.SPE_BOOK_OF_THE_DEAD
                ? __s_recite
                : __s_memorize
        ));
    }

    cptr.stPtro(svc, $context_info_spbook, spellbook);
    if (cptr.ldPtro(svc, $context_info_spbook))
        cptr.stI32o(
            svc,
            $context_info_spbook + $book_info_o_id,
            cptr.ldI32o(cptr.ldPtro(svc, $context_info_spbook), $obj_o_id)
        );
    set_occupation(learn, __s_studying, 0n);
    return 1;
}

