/*
 * This is the parser for the hilite options.
 *
 * parse_status_hl1() separates each hilite entry into
 * a set of field threshold/action component strings,
 * then calls parse_status_hl2() to parse further
 * and configure the hilite.
 */
/** C ref: botl.c:2593 — @param {CPtr<char>} op @param {CInt} from_configfile @returns {CInt} */
function* parse_status_hl1(op, from_configfile) {
    let hsbuf = (function () {
        const flat = new Uint8Array(21 * (128 * 1));
        const a = [];
        for (let r = 0; r < 21; r++) a.push(flat.subarray(r * (128 * 1), (r + 1) * (128 * 1)));
        a.buf = flat;
        return a;
    })();
    let rslt;
    let badopt = 0;
    let i;
    let fldnum;
    let ccount = 0;
    let c;

    fldnum = 0;
    for (i = 0; i < 21; ++i) {
        cptr.st1o(cptr.decay(hsbuf[i]), 0, 0, 1);
    }
    while (cptr.ld1s(op) && fldnum < 21 && ccount < 126) {
        c = lowc(cptr.ld1s(op));
        if (c == 32) {
            if (fldnum >= 1) {
                if (fldnum == 1 && (yield* strncmpi(cptr.decay((hsbuf[0])), (__s_title), -1)) == 0) {
                    /* spaces are allowed in title */
                    cptr.st1o(cptr.decay(hsbuf[fldnum]), ccount++, c, 1);
                    cptr.st1o(cptr.decay(hsbuf[fldnum]), ccount, 0, 1);
                    op = cptr.add(op, 1);
                    continue;
                }
                rslt = (yield* parse_status_hl2(cptr.decay(hsbuf), from_configfile));
                if (!rslt) {
                    badopt = 1;
                    break;
                }
            }
            for (i = 0; i < 21; ++i) {
                cptr.st1o(cptr.decay(hsbuf[i]), 0, 0, 1);
            }
            fldnum = 0;
            ccount = 0;
        } else if (c == 47) {
            fldnum++;
            ccount = 0;
        } else {
            cptr.st1o(cptr.decay(hsbuf[fldnum]), ccount++, c, 1);
            cptr.st1o(cptr.decay(hsbuf[fldnum]), ccount, 0, 1);
        }
        op = cptr.add(op, 1);
    }
    if (fldnum >= 1 && !badopt) {
        rslt = (yield* parse_status_hl2(cptr.decay(hsbuf), from_configfile));
        if (!rslt)
            badopt = 1;
    }
    if (badopt)
        return 0;
    /* make sure highlighting is On; use short duration for temp highlights */
    if (!cptr.ldI64o(iflags, $instance_flags_hilite_delta))
        cptr.stI64o(iflags, $instance_flags_hilite_delta, 3n);
    return 1;
}

/* is str in the format of "[<>]?=?[-+]?[0-9]+%?" regex */
/** C ref: botl.c:2652 — @param {CPtr<char>} str @returns {CInt} */
function is_ltgt_percentnumber(str) {
    let s = str;

    if (cptr.ld1s(s) == 60 || cptr.ld1s(s) == 62)
        s = cptr.add(s, 1);
    if (cptr.ld1s(s) == 61)
        s = cptr.add(s, 1);
    if (cptr.ld1s(s) == 45 || cptr.ld1s(s) == 43)
        s = cptr.add(s, 1);
    if (!digit(cptr.ld1s(s)))
        return 0;
    while (digit(cptr.ld1s(s)))
        s = cptr.add(s, 1);
    if (cptr.ld1s(s) == 37)
        s = cptr.add(s, 1);
    return schar((cptr.ld1s(s) == 0));
}

/* does str only contain "<>=-+0-9%" chars */
/** C ref: botl.c:2673 — @param {CPtr<char>} str @returns {CInt} */
function has_ltgt_percentnumber(str) {
    let s = str;

    while (cptr.ld1s(s)) {
        if (!cptr.strchr(__s_0123456789$botl, cptr.ld1s(s)))
            return 0;
        s = cptr.add(s, 1);
    }
    return 1;
}

