/**
 * C ref: botl.c:2747
 * @param {CPtr<char>} querystr
 * @param {CPtr<char *>} arr
 * @param {CInt} arrmin
 * @param {CInt} arrmax
 * @returns {CInt}
 */
function* query_arrayvalue(querystr, arr, arrmin, arrmax) {
    let i;
    let res;
    let ret = (arrmin - 1) | 0;
    let tmpwin;
    let any = cptr.alloc(8);
    let picks = cptr.box(null);
    let adj = (arrmin > 0) ? 1 : arrmax;
    let clr = NHM.NO_COLOR;

    tmpwin = (yield* Y.icall(create_nhwindow()(NHM.NHW_MENU)));
    (yield* Y.icall(start_menu()(tmpwin, 0n)));

    for (i = arrmin; i < arrmax; i++) {
        if (!cptr.ldPtro(arr, i, 8))
            continue;  /*... set to Null between Satiated and Hungry     */
        cptr.memcpy(any, cptr.add(cg, $const_globals_zeroany), 8);
        cptr.stI32(any, (i + adj) | 0);
        (yield* add_menu(
            tmpwin,
            nul_glyphinfo.v,
            any,
            0,
            0,
            NHM.ATR_NONE,
            clr,
            cptr.ldPtro(arr, i, 8),
            NHM.MENU_ITEMFLAGS_NONE
        ));
    }

    (yield* Y.icall(end_menu()(tmpwin, querystr)));

    res = (yield* select_menu(tmpwin, NHM.PICK_ONE, picks));
    (yield* Y.icall(destroy_nhwindow()(tmpwin)));
    if (res > 0) {
        ret = (cptr.ldI32(picks.v) - adj) | 0;
        cptr.free(picks.v);
    }

    return ret;
}

/** C ref: botl.c:2784 — @param {CInt} fld @param {CPtr<struct hilite_s>} hilite */
function* status_hilite_add_threshold(fld, hilite) {
    let new_hilite;
    let old_hilite;

    if (!hilite)
        return;

    /* alloc and initialize a new hilite_s struct */
    new_hilite = (yield* alloc(128));
    cptr.memcpy(new_hilite, hilite, 128);  /* copy struct */

    cptr.st1o(new_hilite, $hilite_s_set, 1);
    cptr.stI32(new_hilite, fld);
    cptr.stPtro(new_hilite, $hilite_s_next, null);
    /* insert new entry at the end of the list */
    if (!cptr.ldPtro3(gb, 0, $sizeof_istat_s_x27, fld, $sizeof_istat_s, $istat_s_thresholds)) {
        cptr.stPtro3(
            gb,
            0,
            $sizeof_istat_s_x27,
            fld,
            $sizeof_istat_s,
            $istat_s_thresholds,
            new_hilite
        );
    } else {
        for (
            old_hilite = cptr.ldPtro3(
                gb,
                0,
                $sizeof_istat_s_x27,
                fld,
                $sizeof_istat_s,
                $istat_s_thresholds
            );
            cptr.ldPtro(old_hilite, $hilite_s_next);
            old_hilite = cptr.ldPtro(old_hilite, $hilite_s_next)
        )
            continue;
        cptr.stPtro(old_hilite, $hilite_s_next, new_hilite);
    }
    /* sort_hilites(fld) */

    /* current and prev must both point at the same hilites */
    cptr.stPtro3(
        gb,
        1,
        $sizeof_istat_s_x27,
        fld,
        $sizeof_istat_s,
        $istat_s_thresholds,
        cptr.ldPtro3(gb, 0, $sizeof_istat_s_x27, fld, $sizeof_istat_s, $istat_s_thresholds)
    );
}

