/* The "do we or do we not give the intrinsic" logic from givit(), extracted
 * into its own function. Depends on the monster's level and the type of
 * intrinsic it is trying to give you.
 */
/** C ref: eat.c:961 — @param {CInt} type @param {CPtr<struct permonst>} ptr @returns {CInt} */
function should_givit(type, ptr) {
    let chance;

    /* some intrinsics are easier to get than others */
    switch (type) {
        case NHC.POISON_RES:
            if ((cptr.eq(ptr, cptr.add(mons, NHC.PM_KILLER_BEE, $sizeof_permonst)) ||
                cptr.eq(ptr, cptr.add(mons, NHC.PM_SCORPION, $sizeof_permonst))) &&
                    !rn2(4))
                chance = 1;
            else
                chance = 15;
            break;
        case NHC.TELEPORT:
            chance = 10;
            break;
        case NHC.TELEPORT_CONTROL:
            chance = 12;
            break;
        case NHC.TELEPAT:
            chance = 1;
            break;
        default:
            chance = 15;
            break;
    }

    return schar((cptr.ld1so(ptr, $permonst_mlevel) > rn2(chance)));
}

/** C ref: eat.c:992 — @param {CInt} type @param {CPtr<struct permonst>} ptr @returns {CInt} */
function temp_givit(type, ptr) {
    let chance = (type == NHC.STONE_RES) ? 6 : ((type == NHC.ACID_RES) ? 3 : 0);

    return schar((chance ? (cptr.ld1so(ptr, $permonst_mlevel) > rn2(chance)) : 0));
}

