    if (cptr.eq(otmp, uquiver.v) && cptr.ldI64o(otmp, $obj_quan) == 1n)
        (yield* uqwepgone());
    if (cptr.eq(otmp, uswapwep.v) && cptr.ldI64o(otmp, $obj_quan) == 1n)
        (yield* uswapwepgone());

