                (cptr.stI32o(u, $you_mh, cptr.ldI32o(u, $you_mh) + 1)) - (1), cptr.st1(disp, 1);
            if (cptr.ldI32o(u, $you_uhp) < cptr.ldI32o(u, $you_uhpmax))
                (cptr.stI32o(u, $you_uhp, cptr.ldI32o(u, $you_uhp) + 1)) - (1), cptr.st1(disp, 1);
