        return NHC.GETOBJ_SUGGEST;

    if (cptr.ldI16o(obj, $obj_otyp) == NHC.POT_OIL &&
            (cptr.ldI32o(obj, $obj_dknown) & 1) | 0 &&
            (cptr.ldI32o2(objects, NHC.POT_OIL, $sizeof_objclass, $objclass_oc_name_known) & 1) | 0)
        return NHC.GETOBJ_SUGGEST;

