/** C ref: sounds.c:351 — @param {CPtr<struct monst>} mtmp @returns {CPtr<char>} */
function growl_sound(mtmp) {
    let ret;

    switch (cptr.ld1uo(cptr.ldPtro(mtmp, $monst_data), $permonst_msound)) {
        case NHC.MS_MEW:
        case NHC.MS_HISS:
            ret = __s_hiss;
            break;
        case NHC.MS_BARK:
        case NHC.MS_GROWL:
            ret = __s_growl;
            break;
        case NHC.MS_ROAR:
            ret = __s_roar;
            break;
        case NHC.MS_BELLOW:
            ret = __s_bellow;
            break;
        case NHC.MS_BUZZ:
            ret = __s_buzz;
            break;
        case NHC.MS_SQEEK:
            ret = __s_squeal;
            break;
        case NHC.MS_SQAWK:
            ret = __s_screech;
            break;
        case NHC.MS_NEIGH:
            ret = __s_neigh;
            break;
        case NHC.MS_WAIL:
            ret = __s_wail;
            break;
        case NHC.MS_GROAN:
            ret = __s_groan;
            break;
        case NHC.MS_MOO:
            ret = __s_low;
            break;
        case NHC.MS_SILENT:
            ret = __s_commotion;
            break;
        default:
            ret = __s_scream;
    }
    return ret;
}

