/* pet makes "I'm hungry" noises */
/** C ref: sounds.c:519 — @param {CPtr<struct monst>} mtmp */
function* beg(mtmp) {
    if (helpless(mtmp) ||
            !(((cptr.ldU64o((cptr.ldPtro(mtmp, $monst_data)), $permonst_mflags1) & 536870912n) !=
                0n) ||
                ((cptr.ldU64o((cptr.ldPtro(mtmp, $monst_data)), $permonst_mflags1) &
                    1073741824n) != 0n)))
        return;

    /* presumably nearness and soundok checks have already been made */
    if (!(cptr.ld1uo((cptr.ldPtro(mtmp, $monst_data)), $permonst_msound) == NHC.MS_SILENT) &&
            cptr.ld1uo(cptr.ldPtro(mtmp, $monst_data), $permonst_msound) <= NHC.MS_ANIMAL) {
        void (yield* domonnoise(mtmp));
    } else if (cptr.ld1uo(cptr.ldPtro(mtmp, $monst_data), $permonst_msound) >= NHC.MS_HUMANOID) {
        if (!canspotmon(mtmp))
            (yield* map_invisible(cptr.ldI16o(mtmp, $monst_mx), cptr.ldI16o(mtmp, $monst_my)));
        ;
        (yield* verbalize(__s_i_m_hungry));
    } else {
        /* this is pretty lame but is better than leaving out the block
           of speech types between animal and humanoid; this covers
           MS_SILENT too (if caller lets that get this far) since it's
           excluded by the first two cases */
        if (canspotmon(mtmp))
            (yield* pline(__s_s_seems_famished, (yield* Monnam(mtmp))));
        /* looking famished will be a good trick for a tame skeleton... */
    }
}

