/** C ref: vault.c:646 — @param {CPtr<struct monst>} grd */
function* wallify_vault(grd) {
    let typ;
    let x;
    let y;
    let vlt = cptr.ldI32o(
        (cptr.ldPtro(cptr.ldPtro((grd), $monst_mextra), $mextra_egd)),
        $egd_vroom
    );
    let tmp_viz;
    let lox = i16(((cptr.ldI16o(svr, vlt, $sizeof_mkroom) - 1) | 0));
    let hix = i16(((cptr.ldI16o2(svr, vlt, $sizeof_mkroom, $mkroom_hx) + 1) | 0));
    let loy = i16(((cptr.ldI16o2(svr, vlt, $sizeof_mkroom, $mkroom_ly) - 1) | 0));
    let hiy = i16(((cptr.ldI16o2(svr, vlt, $sizeof_mkroom, $mkroom_hy) + 1) | 0));
    let mon;
    let gold;
    let rocks;
    let trap;
    let fixed = 0;
    let movedgold = 0;

    for (x = lox; x <= hix; x++)
        for (y = loy; y <= hiy; y++) {
            /* if not on the room boundary, skip ahead */
            if (x != lox && x != hix && y != loy && y != hiy)
                continue;

            if ((!((cptr.ld1so3(
                svl,
                x,
                $sizeof_rm_x21,
                y,
                $sizeof_rm,
                $instance_globals_saved_l_level + $rm_typ
            )) &&
                (cptr.ld1so3(
                    svl,
                    x,
                    $sizeof_rm_x21,
                    y,
                    $sizeof_rm,
                    $instance_globals_saved_l_level + $rm_typ
                )) <=
                    NHC.DBWALL) ||
                g_at(x, y) ||
                sobj_at(NHC.ROCK, x, y) ||
                sobj_at(NHC.BOULDER, x, y)) &&
                    !in_fcorridor(grd, x, y)) {
                if ((mon = (cptr.ldPtro3(
                    svl,
                    x,
                    168,
                    y,
                    8,
                    $instance_globals_saved_l_level + $dlevel_t_monsters
                ))) !==
                    null &&
                        !cptr.eq(mon, grd)) {
                    if (cptr.ld1so(mon, $monst_mtame))
                        (yield* yelp(mon));
                    if (!(yield* rloc(mon, NHM.RLOC_MSG)))
                        (yield* m_into_limbo(mon));
                }
                /* move gold at wall locations into the vault */
                if ((gold = g_at(x, y)) !== null) {
                    (yield* move_gold(
                        gold,
                        cptr.ldI32o(
                            (cptr.ldPtro(cptr.ldPtro((grd), $monst_mextra), $mextra_egd)),
                            $egd_vroom
                        )
                    ));
                    movedgold = 1;
                }
                /* destroy rocks and boulders (subsume them into the walls);
                   other objects present stay intact and become embedded */
                while ((rocks = sobj_at(NHC.ROCK, x, y)) !== null) {
                    (yield* obj_extract_self(rocks));
                    (yield* obfree(rocks, null));
                }
                while ((rocks = sobj_at(NHC.BOULDER, x, y)) !== null) {
                    (yield* obj_extract_self(rocks));
                    (yield* obfree(rocks, null));
                }
                if ((trap = t_at(x, y)) !== null)
                    (yield* deltrap(trap));

                if (x == lox)
                    typ = (y == loy) ? NHC.TLCORNER : ((y == hiy) ? NHC.BLCORNER : NHC.VWALL);
                else if (x == hix)
                    typ = (y == loy) ? NHC.TRCORNER : ((y == hiy) ? NHC.BRCORNER : NHC.VWALL);
                else
                    typ = NHC.HWALL;

                cptr.st1o3(
                    svl,
                    x,
                    $sizeof_rm_x21,
                    y,
                    $sizeof_rm,
                    $instance_globals_saved_l_level + $rm_typ,
                    schar(typ)
                );
                cptr.stI32o3(
                    svl,
                    x,
                    $sizeof_rm_x21,
                    y,
                    $sizeof_rm,
                    $instance_globals_saved_l_level + $rm_flags,
                    0
                );
                xy_set_wall_state(x, y);  /* set WA_MASK bits in .wall_info */
                (yield* del_engr_at(x, y));
                /*
                 * hack: player knows walls are restored because of the
                 * message, below, so show this on the screen.
                 */
                tmp_viz = schar(cptr.ld1uo(
                    cptr.ldPtro(cptr.ldPtro(gv, $instance_globals_v_viz_array), y, 8),
                    x
                ));
                cptr.st1o(cptr.ldPtro(cptr.ldPtro(gv, $instance_globals_v_viz_array), y, 8), x, 3);
                (yield* newsym(x, y));
                cptr.st1o(
                    cptr.ldPtro(cptr.ldPtro(gv, $instance_globals_v_viz_array), y, 8),
                    x,
                    uchar(tmp_viz)
                );
                (yield* block_point(x, y));
                fixed = 1;
            }
        }

    if (movedgold || fixed) {
        if (in_fcorridor(grd, cptr.ldI16o(grd, $monst_mx), cptr.ldI16o(grd, $monst_my)) ||
                ((cptr.ld1uo(
                    cptr.ldPtro(
                        cptr.ldPtro(gv, $instance_globals_v_viz_array),
                        cptr.ldI16o(grd, $monst_my),
                        8
                    ),
                    cptr.ldI16o(grd, $monst_mx)
                ) &
                    NHM.IN_SIGHT) != 0))
            (yield* pline(__s_s_whispers_an_incantation, (yield* noit_Monnam(grd))));
        else
            (yield* You_hear(__s_a_distant_chant));
        if (movedgold)
            (yield* pline(__s_a_mysterious_force_moves_the_gold_into));
        if (fixed)
            (yield* pline_The(__s_damaged_vault_s_walls_are_magically));
    }
}

