    cptr.stI16o(reg, $NhRegion_max_monst, 0);
    cptr.stPtro(reg, $NhRegion_monsters, null);
    cptr.memcpy(cptr.add(reg, $NhRegion_arg), cptr.add(cg, $const_globals_zeroany), 8);
