        cptr.stI16o(reg, $nhrect_hx, cptr.ldI16o(rect, $NhRect_hx));
    if (cptr.ldI16o(reg, $nhrect_hy) < cptr.ldI16o(rect, $NhRect_hy))
        cptr.stI16o(reg, $nhrect_hy, cptr.ldI16o(rect, $NhRect_hy));
