/*
 * check whether a monster enters/leaves one or more regions.
 */
/**
 * C ref: region.c:533
 * @param {CPtr<struct monst>} mon
 * @param {CInt} x
 * @param {CInt} y
 * @returns {CInt}
 */
function* m_in_out_region(mon, x, y) {
    let i;
    let f_indx = 0;

    /* First check if mon can do the move */
    for (i = 0; i < cptr.ldI32o(svn, $instance_globals_saved_n_n_regions); i++) {
        if (cptr.ldI32o(
            cptr.ldPtro(cptr.ldPtro(gr, $instance_globals_r_regions), i, 8),
            $NhRegion_attach_2_m
        ) ==
                cptr.ldI32o(mon, $monst_m_id))
            continue;
        if (inside_region(cptr.ldPtro(cptr.ldPtro(gr, $instance_globals_r_regions), i, 8), x, y)
                ? (!mon_in_region(
                    cptr.ldPtro(cptr.ldPtro(gr, $instance_globals_r_regions), i, 8),
                    mon
                ) &&
                    (f_indx = cptr.ldI16o(
                        cptr.ldPtro(cptr.ldPtro(gr, $instance_globals_r_regions), i, 8),
                        $NhRegion_can_enter_f
                    )) != -1
                    ? 1
                    : 0)
                : (mon_in_region(
                    cptr.ldPtro(cptr.ldPtro(gr, $instance_globals_r_regions), i, 8),
                    mon
                ) &&
                    (f_indx = cptr.ldI16o(
                        cptr.ldPtro(cptr.ldPtro(gr, $instance_globals_r_regions), i, 8),
                        $NhRegion_can_leave_f
                    )) != -1
                    ? 1
                    : 0)) {
            if (!(yield* Y.icall((callbacks[f_indx])(
                cptr.ldPtro(cptr.ldPtro(gr, $instance_globals_r_regions), i, 8),
                mon
            ))))
                return 0;
        }
    }

    /* Callbacks for the regions mon does leave */
    for (i = 0; i < cptr.ldI32o(svn, $instance_globals_saved_n_n_regions); i++) {
        if (cptr.ldI32o(
            cptr.ldPtro(cptr.ldPtro(gr, $instance_globals_r_regions), i, 8),
            $NhRegion_attach_2_m
        ) ==
                cptr.ldI32o(mon, $monst_m_id))
            continue;
        if (mon_in_region(cptr.ldPtro(cptr.ldPtro(gr, $instance_globals_r_regions), i, 8), mon) &&
                !inside_region(
                    cptr.ldPtro(cptr.ldPtro(gr, $instance_globals_r_regions), i, 8),
                    x,
                    y
                )) {
            remove_mon_from_reg(
                cptr.ldPtro(cptr.ldPtro(gr, $instance_globals_r_regions), i, 8),
                mon
            );
            if ((f_indx = cptr.ldI16o(
                cptr.ldPtro(cptr.ldPtro(gr, $instance_globals_r_regions), i, 8),
                $NhRegion_leave_f
            )) != -1)
                void (yield* Y.icall((callbacks[f_indx])(
                    cptr.ldPtro(cptr.ldPtro(gr, $instance_globals_r_regions), i, 8),
                    mon
                )));
        }
    }

    /* Callbacks for the regions mon does enter */
    for (i = 0; i < cptr.ldI32o(svn, $instance_globals_saved_n_n_regions); i++) {
        if (cptr.ldI32o(
            cptr.ldPtro(cptr.ldPtro(gr, $instance_globals_r_regions), i, 8),
            $NhRegion_attach_2_m
        ) ==
                cptr.ldI32o(mon, $monst_m_id))
            continue;
        if (!mon_in_region(cptr.ldPtro(cptr.ldPtro(gr, $instance_globals_r_regions), i, 8), mon) &&
                inside_region(
                    cptr.ldPtro(cptr.ldPtro(gr, $instance_globals_r_regions), i, 8),
                    x,
                    y
                )) {
            (yield* add_mon_to_reg(cptr.ldPtro(cptr.ldPtro(gr, $instance_globals_r_regions), i, 8), mon));
            if ((f_indx = cptr.ldI16o(
                cptr.ldPtro(cptr.ldPtro(gr, $instance_globals_r_regions), i, 8),
                $NhRegion_enter_f
            )) != -1)
                void (yield* Y.icall((callbacks[f_indx])(
                    cptr.ldPtro(cptr.ldPtro(gr, $instance_globals_r_regions), i, 8),
                    mon
                )));
        }
    }

    return 1;
}

