/* some monster-types can't vomit */
/** C ref: mondata.c:663 — @param {CPtr<struct permonst>} ptr @returns {CInt} */
function cantvomit(ptr) {
    /* rats and mice are incapable of vomiting; likewise with horses;
       which other creatures have the same limitation? */
    if (cptr.ld1so(ptr, $permonst_mlet) == NHC.S_RODENT &&
            !cptr.eq(ptr, cptr.add(mons, NHC.PM_ROCK_MOLE, $sizeof_permonst)) &&
            !cptr.eq(ptr, cptr.add(mons, NHC.PM_WOODCHUCK, $sizeof_permonst)))
        return 1;
    if (cptr.eq(ptr, cptr.add(mons, NHC.PM_WARHORSE, $sizeof_permonst)) ||
            cptr.eq(ptr, cptr.add(mons, NHC.PM_HORSE, $sizeof_permonst)) ||
            cptr.eq(ptr, cptr.add(mons, NHC.PM_PONY, $sizeof_permonst)))
        return 1;
    return 0;
}

/* number of horns this type of monster has on its head */
/** C ref: mondata.c:678 — @param {CPtr<struct permonst>} ptr @returns {CInt} */
function num_horns(ptr) {
    switch ((cptr.ldI32o((ptr), $permonst_pmidx))) {
        case NHC.PM_HORNED_DEVIL:
        case NHC.PM_MINOTAUR:
        case NHC.PM_ASMODEUS:
        case NHC.PM_BALROG:
            return 2;
        case NHC.PM_WHITE_UNICORN:
        case NHC.PM_GRAY_UNICORN:
        case NHC.PM_BLACK_UNICORN:
        case NHC.PM_KI_RIN:
            return 1;
        default:
            break;
    }
    return 0;
}

/* does monster-type deal out a particular type of damage from a particular
   type of attack? */
/**
 * C ref: mondata.c:700
 * @param {CPtr<struct permonst>} ptr
 * @param {CInt} dtyp
 * @param {CInt} atyp
 * @returns {CPtr<struct attack>}
 */
function dmgtype_fromattack(ptr, dtyp, atyp) {
    let a;

    for (
        a = cptr.add(cptr.add(ptr, $permonst_mattk), 0, $sizeof_attack);
        cptr.cmp(a, cptr.add(cptr.add(ptr, $permonst_mattk), NHM.NATTK, $sizeof_attack)) < 0;
        a = cptr.add(a, 1, 4)
    )
        if (cptr.ld1uo(a, $attack_adtyp) == dtyp && (atyp == -1 || cptr.ld1u(a) == atyp))
            return a;
    return null;
}

/* does monster-type deal out a particular type of damage from any attack */
/** C ref: mondata.c:712 — @param {CPtr<struct permonst>} ptr @param {CInt} dtyp @returns {CInt} */
function dmgtype(ptr, dtyp) {
    return schar((dmgtype_fromattack(ptr, dtyp, -1) ? 1 : 0));
}

/* returns the maximum damage a defender can do to the attacker via
   a passive defense */
/**
 * C ref: mondata.c:720
 * @param {CPtr<struct monst>} mdef
 * @param {CPtr<struct monst>} magr
 * @returns {CInt}
 */
function* max_passive_dmg(mdef, magr) {
    let i;
    let dmg;
    let multi2 = 0;
    let adtyp;

    /* each attack by magr can result in passive damage */
    for (i = 0; i < NHM.NATTK; i++)
        switch (cptr.ld1uo2(cptr.ldPtro(magr, $monst_data), i, $sizeof_attack, $permonst_mattk)) {
            case NHM.AT_CLAW:
            case NHM.AT_BITE:
            case NHM.AT_KICK:
            case NHM.AT_BUTT:
            case NHM.AT_TUCH:
            case NHM.AT_STNG:
            case NHM.AT_HUGS:
            case NHM.AT_ENGL:
            case NHM.AT_TENT:
            case NHM.AT_WEAP:
                multi2++;
                break;
            default:
                break;
        }

    dmg = 0;
    for (i = 0; i < NHM.NATTK; i++)
        if (cptr.ld1uo2(cptr.ldPtro(mdef, $monst_data), i, $sizeof_attack, $permonst_mattk) ==
            NHM.AT_NONE ||
                cptr.ld1uo2(cptr.ldPtro(mdef, $monst_data), i, $sizeof_attack, $permonst_mattk) ==
                    NHM.AT_BOOM) {
            adtyp = cptr.ld1uo2(
                cptr.ldPtro(mdef, $monst_data),
                i,
                $sizeof_attack,
                $permonst_mattk + $attack_adtyp
            );
            if ((adtyp == NHM.AD_FIRE && completelyburns(cptr.ldPtro(magr, $monst_data))) ||
                    (adtyp == NHM.AD_DCAY && completelyrots(cptr.ldPtro(magr, $monst_data))) ||
                    (adtyp == NHM.AD_RUST &&
                        (cptr.eq(
                            (cptr.ldPtro(magr, $monst_data)),
                            cptr.add(mons, NHC.PM_IRON_GOLEM, $sizeof_permonst)
                        )))) {
                dmg = cptr.ldI32o(magr, $monst_mhp);
            } else if ((adtyp == NHM.AD_ACID && !(yield* Resists_Elem(magr, NHC.ACID_RES))) ||
                    (adtyp == NHM.AD_COLD && !(yield* Resists_Elem(magr, NHC.COLD_RES))) ||
                    (adtyp == NHM.AD_FIRE && !(yield* Resists_Elem(magr, NHC.FIRE_RES))) ||
                    (adtyp == NHM.AD_ELEC && !(yield* Resists_Elem(magr, NHC.SHOCK_RES))) ||
                    adtyp == NHM.AD_PHYS) {
                dmg = cptr.ld1uo2(
                    cptr.ldPtro(mdef, $monst_data),
                    i,
                    $sizeof_attack,
                    $permonst_mattk + $attack_damn
                );
                if (!dmg)
                    dmg = (cptr.ld1so(cptr.ldPtro(mdef, $monst_data), $permonst_mlevel) + 1) | 0;
                dmg = Math.imul(
                    dmg,
                    cptr.ld1uo2(
                        cptr.ldPtro(mdef, $monst_data),
                        i,
                        $sizeof_attack,
                        $permonst_mattk + $attack_damd
                    )
                );
            }
            dmg = Math.imul(dmg, multi2);
            break;
        }
    return dmg;
}

/* determine whether two monster types are from the same species */
/**
 * C ref: mondata.c:771
 * @param {CPtr<struct permonst>} pm1
 * @param {CPtr<struct permonst>} pm2
 * @returns {CInt}
 */
function same_race(pm1, pm2) {
    let let1 = cptr.ld1so(pm1, $permonst_mlet);
    let let2 = cptr.ld1so(pm2, $permonst_mlet);

    if (cptr.eq(pm1, pm2))
        return 1;  /* exact match */
    /* player races have their own predicates */
    if (((cptr.ldU64o((pm1), $permonst_mflags2) & 8n) != 0n))
        return schar(((cptr.ldU64o((pm2), $permonst_mflags2) & 8n) != 0n));
    if (((cptr.ldU64o((pm1), $permonst_mflags2) & 16n) != 0n))
        return schar(((cptr.ldU64o((pm2), $permonst_mflags2) & 16n) != 0n));
    if (((cptr.ldU64o((pm1), $permonst_mflags2) & 32n) != 0n))
        return schar(((cptr.ldU64o((pm2), $permonst_mflags2) & 32n) != 0n));
    if (((cptr.ldU64o((pm1), $permonst_mflags2) & 64n) != 0n))
        return schar(((cptr.ldU64o((pm2), $permonst_mflags2) & 64n) != 0n));
    if (((cptr.ldU64o((pm1), $permonst_mflags2) & 128n) != 0n))
        return schar(((cptr.ldU64o((pm2), $permonst_mflags2) & 128n) != 0n));
    /* other creatures are less precise */
    if (((cptr.ldU64o((pm1), $permonst_mflags2) & 8192n) != 0n))
        return schar(((cptr.ldU64o((pm2), $permonst_mflags2) & 8192n) != 0n));  /* open to quibbling here */
    if ((cptr.ld1so((pm1), $permonst_mlet) == NHC.S_GOLEM))
        return schar((cptr.ld1so((pm2), $permonst_mlet) == NHC.S_GOLEM));  /* even moreso... */
    if (is_mind_flayer(pm1))
        return schar(is_mind_flayer(pm2));
    if (let1 == NHC.S_KOBOLD ||
            cptr.eq(pm1, cptr.add(mons, NHC.PM_KOBOLD_ZOMBIE, $sizeof_permonst)) ||
            cptr.eq(pm1, cptr.add(mons, NHC.PM_KOBOLD_MUMMY, $sizeof_permonst)))
        return schar((let2 == NHC.S_KOBOLD ||
            cptr.eq(pm2, cptr.add(mons, NHC.PM_KOBOLD_ZOMBIE, $sizeof_permonst)) ||
            cptr.eq(pm2, cptr.add(mons, NHC.PM_KOBOLD_MUMMY, $sizeof_permonst))
                ? 1
                : 0));
    if (let1 == NHC.S_OGRE)
        return schar((let2 == NHC.S_OGRE));
    if (let1 == NHC.S_NYMPH)
        return schar((let2 == NHC.S_NYMPH));
    if (let1 == NHC.S_CENTAUR)
        return schar((let2 == NHC.S_CENTAUR));
    if (is_unicorn(pm1))
        return schar(is_unicorn(pm2));
    if (let1 == NHC.S_DRAGON)
        return schar((let2 == NHC.S_DRAGON));
    if (let1 == NHC.S_NAGA)
        return schar((let2 == NHC.S_NAGA));
    /* other critters get steadily messier */
    if (is_rider(pm1))
        return schar(is_rider(pm2));  /* debatable */
    if (((cptr.ldU64o((pm1), $permonst_mflags2) & 4096n) != 0n))
        return schar(((cptr.ldU64o((pm2), $permonst_mflags2) & 4096n) != 0n));  /* [needs work?] */
    /* tengu don't match imps (first test handled case of both being tengu) */
    if (cptr.eq(pm1, cptr.add(mons, NHC.PM_TENGU, $sizeof_permonst)) ||
            cptr.eq(pm2, cptr.add(mons, NHC.PM_TENGU, $sizeof_permonst)))
        return 0;
    if (let1 == NHC.S_IMP)
        return schar((let2 == NHC.S_IMP));
    else if (let2 == NHC.S_IMP)
        return 0;
    if (((cptr.ldU64o((pm1), $permonst_mflags2) & 256n) != 0n))
        return schar(((cptr.ldU64o((pm2), $permonst_mflags2) & 256n) != 0n));
    if (((cptr.ldU64o((pm1), $permonst_mflags2) & 2n) != 0n)) {
        if (let1 == NHC.S_ZOMBIE)
            return schar((let2 == NHC.S_ZOMBIE));
        if (let1 == NHC.S_MUMMY)
            return schar((let2 == NHC.S_MUMMY));
        if (let1 == NHC.S_VAMPIRE)
            return schar((let2 == NHC.S_VAMPIRE));
        if (let1 == NHC.S_LICH)
            return schar((let2 == NHC.S_LICH));
        if (let1 == NHC.S_WRAITH)
            return schar((let2 == NHC.S_WRAITH));
        if (let1 == NHC.S_GHOST)
            return schar((let2 == NHC.S_GHOST));
    } else if (((cptr.ldU64o((pm2), $permonst_mflags2) & 2n) != 0n))
        return 0;

    /* check for monsters which grow into more mature forms */
    if (let1 == let2) {
        let m1 = (cptr.ldI32o((pm1), $permonst_pmidx));
        let m2 = (cptr.ldI32o((pm2), $permonst_pmidx));
        let prv;
        let nxt;

        /* we know m1 != m2 (very first check above); test all smaller
           forms of m1 against m2, then all larger ones; don't need to
           make the corresponding tests for variants of m2 against m1 */
        for (prv = m1, nxt = big_to_little(m1); nxt != prv; prv = nxt, nxt = big_to_little(nxt))
            if (nxt == m2)
                return 1;
        for (prv = m1, nxt = little_to_big(m1); nxt != prv; prv = nxt, nxt = little_to_big(nxt))
            if (nxt == m2)
                return 1;
    }
    /* not caught by little/big handling */
    if (cptr.eq(pm1, cptr.add(mons, NHC.PM_GARGOYLE, $sizeof_permonst)) ||
            cptr.eq(pm1, cptr.add(mons, NHC.PM_WINGED_GARGOYLE, $sizeof_permonst)))
        return schar((cptr.eq(pm2, cptr.add(mons, NHC.PM_GARGOYLE, $sizeof_permonst)) ||
            cptr.eq(pm2, cptr.add(mons, NHC.PM_WINGED_GARGOYLE, $sizeof_permonst))
                ? 1
                : 0));
    if (cptr.eq(pm1, cptr.add(mons, NHC.PM_KILLER_BEE, $sizeof_permonst)) ||
            cptr.eq(pm1, cptr.add(mons, NHC.PM_QUEEN_BEE, $sizeof_permonst)))
        return schar((cptr.eq(pm2, cptr.add(mons, NHC.PM_KILLER_BEE, $sizeof_permonst)) ||
            cptr.eq(pm2, cptr.add(mons, NHC.PM_QUEEN_BEE, $sizeof_permonst))
                ? 1
                : 0));

    if (is_longworm(pm1))
        return schar(is_longworm(pm2));  /* handles tail */
    /* [currently there's no reason to bother matching up
        assorted bugs and blobs with their closest variants] */
    /* didn't match */
    return 0;
}

/* for handling alternate spellings */
/** C ref: mondata.c:874 — struct alt_spl { name, pm_val, genderhint } (memory model v0.5) */

/* figure out what type of monster a user-supplied string is specifying;
   ignore anything past the monster name */
/**
 * C ref: mondata.c:883
 * @param {CPtr<char>} in_str
 * @param {CPtr<int>} gender_name_var
 * @returns {CInt}
 */
function* name_to_mon(in_str, gender_name_var) {
    return (yield* name_to_monplus(in_str, null, gender_name_var));
}

