    (yield* place_monster(mtmp, x, y));  /* put monster down */
    (yield* update_monster_region(mtmp));

    if ((cptr.ldI32o(mtmp, $monst_wormno) & 31))
        (yield* place_worm_tail_randomly(mtmp, x, y));

