    if ((cptr.ldI32o(mtmp, $monst_mtrapped) & 1) | 0 && !(cptr.ldI32o(mtmp, $monst_wormno) & 31))
        void (yield* mintrap(mtmp, NHM.NO_TRAP_FLAGS));
