                /* round 3: shields */
                if (mac < 10 && rn2(3))
                    otmp = (yield* mongets(mtmp, NHC.SMALL_SHIELD));
                else if (mac < 10 && rn2(2))
                    otmp = (yield* mongets(mtmp, NHC.LARGE_SHIELD));
                if (otmp) {
                    mac = (mac + ARM_BONUS(otmp)) | 0;
                }
                otmp = null;
