/**
 * C ref: makemon.c:1076
 * @param {CPtr<struct monst>} mon
 * @param {CUInt} gpflags
 * @param {CPtr<coord>} cc
 * @returns {CInt}
 */
function* makemon_rnd_goodpos(mon, gpflags, cc) {
    let tryct = 0;
    let nx;
    let ny;
    let good;

    gpflags = Number(BigInt.asUintN(32, BigInt(gpflags >>> 0) | 16777216n));
    do {
        nx = i16(((rn2(77) + 2) | 0));
        ny = i16(rn2(NHM.ROWNO));
        good = schar(((!cptr.ld1so(gi, $instance_globals_i_in_mklev) &&
            ((cptr.ld1uo(cptr.ldPtro(cptr.ldPtro(gv, $instance_globals_v_viz_array), ny, 8), nx) &
                NHM.IN_SIGHT) != 0))
                ? 0
                : (yield* goodpos(nx, ny, mon, gpflags))));
    } while ((++tryct < 50) && !good);

    if (!good) {
        /* else go through all map positions, twice, first round
           ignoring positions in sight, and pick first good one.
           skip first round if we're in special level loader or blind */
        let xofs = nx;
        let yofs = ny;
        let dx;
        let dy;
        let bl = (cptr.ld1so(gi, $instance_globals_i_in_mklev) || Blind()) ? 1 : 0;

        for (; bl < 2; bl++) {
            if (!bl)
                gpflags = Number(BigInt.asUintN(32, BigInt(gpflags >>> 0) & (-8388609n)));  /* perhaps should be a 3rd pass */
            for (dx = 0; dx < NHM.COLNO; dx++)
                for (dy = 0; dy < NHM.ROWNO; dy++) {
                    nx = i16((((((dx + xofs) | 0) % 79) + 1) | 0));
                    ny = i16((((((dy + yofs) | 0) % 20) + 1) | 0));
                    if (bl == 0 &&
                            ((cptr.ld1uo(
                                cptr.ldPtro(cptr.ldPtro(gv, $instance_globals_v_viz_array), ny, 8),
                                nx
                            ) &
                                NHM.IN_SIGHT) != 0))
                        continue;
                    if ((yield* goodpos(nx, ny, mon, gpflags)))
                        {
                            cptr.stI16(cc, nx);
                            cptr.stI16o(cc, $coord_y, ny);
                            return 1;
                        }
                }
            if (bl == 0 && (!mon || cptr.ld1so(cptr.ldPtro(mon, $monst_data), $permonst_mmove))) {
                let stway = cptr.ldPtro(gs, $instance_globals_s_stairs);
                /* all map positions are visible (or not good),
                   try to pick something logical */
                while (stway) {
                    if (cptr.ldI16o(stway, $stairway_tolev) == cptr.ldI16o(u, $you_uz) && !rn2(2)) {
                        nx = cptr.ldI16(stway);
                        ny = cptr.ldI16o(stway, $stairway_sy);
                        break;
                    }
                    stway = cptr.ldPtro(stway, $stairway_next);
                }
                if ((yield* goodpos(nx, ny, mon, gpflags)))
                    {
                        cptr.stI16(cc, nx);
                        cptr.stI16o(cc, $coord_y, ny);
                        return 1;
                    }
            }
        }
    } else {
        cptr.stI16(cc, nx);
        cptr.stI16o(cc, $coord_y, ny);
        return 1;
    }
    return 0;
}

