    let allow_minvent = schar(((BigInt(mmflags >>> 0) & 1n) == 0n));
    let countbirth = schar(((BigInt(mmflags >>> 0) & 4n) == 0n));
    let allowtail = schar(((BigInt(mmflags >>> 0) & 16384n) == 0n));
