/* used for monster ID by the '/', ';', and 'C' commands to block remote
   identification of the endgame altars via their attending priests */
/**
 * C ref: do_name.c:1170
 * @param {CPtr<struct monst>} mon
 * @param {CInt} article
 * @param {CPtr<char>} outbuf
 * @returns {CPtr<char>}
 */
function* distant_monnam(mon, article, outbuf) {
    /* high priest(ess)'s identity is concealed on the Astral Plane,
       unless you're adjacent (overridden for hallucination which does
       its own obfuscation) */
    if (cptr.eq(
        cptr.ldPtro(mon, $monst_data),
        cptr.add(mons, NHC.PM_HIGH_CLERIC, $sizeof_permonst)
    ) &&
            !Hallucination() &&
            (((cptr.ldI16o(
                (cptr.add(
                    svd,
                    $instance_globals_saved_d_dungeon_topology + $dgn_topology_d_astral_level
                )),
                $d_level_dlevel
            ) ||
                cptr.ldI16((cptr.add(
                    svd,
                    $instance_globals_saved_d_dungeon_topology + $dgn_topology_d_astral_level
                )))) &&
                on_level(
                    cptr.add(u, $you_uz),
                    cptr.add(
                        svd,
                        $instance_globals_saved_d_dungeon_topology + $dgn_topology_d_astral_level
                    )
                ))) &&
            !m_next2u(mon)) {
        void cptr.strcpy(outbuf, article == NHM.ARTICLE_THE ? __s_the$do_name : __s_empty$do_name);
        void cptr.strcat(
            outbuf,
            (cptr.ldI32o(mon, $monst_female) & 1) | 0 ? __s_high_priestess$do_name : __s_high_priest$do_name
        );
    } else {
        void cptr.strcpy(outbuf, (yield* x_monnam(mon, article, null, 0, 1)));
    }
    return outbuf;
}

/* returns mon_nam(mon) relative to other_mon; normal name unless they're
   the same, in which case the reference is to {him|her|it} self */
/**
 * C ref: do_name.c:1191
 * @param {CPtr<struct monst>} mon
 * @param {CPtr<struct monst>} other_mon
 * @returns {CPtr<char>}
 */
function* mon_nam_too(mon, other_mon) {
    let outbuf;

    if (!cptr.eq(mon, other_mon)) {
        outbuf = (yield* mon_nam(mon));
    } else {
        outbuf = nextmbuf();
        switch (pronoun_gender(mon, NHM.PRONOUN_HALLU)) {
            case 0:
                void cptr.strcpy(outbuf, __s_himself$do_name);
                break;
            case 1:
                void cptr.strcpy(outbuf, __s_herself$do_name);
                break;
            default:
            case 2:
                void cptr.strcpy(outbuf, __s_itself$do_name);
                break;
            case 3:
                void cptr.strcpy(outbuf, __s_themselves$do_name);
                break;
        }
    }
    return outbuf;
}

/* construct "<monnamtext> <verb> <othertext> {him|her|it}self" which might
   be distorted by Hallu; if that's plural, adjust monnamtext and verb */
/**
 * C ref: do_name.c:1221
 * @param {CPtr<struct monst>} mon
 * @param {CPtr<char>} monnamtext
 * @param {CPtr<char>} verb
 * @param {CPtr<char>} othertext
 * @returns {CPtr<char>}
 */
