/* changes the monster into a stone monster of the same type
   this should only be called when poly_when_stoned() is true */
/** C ref: mon.c:3748 — @param {CPtr<struct monst>} mtmp */
function* mon_to_stone(mtmp) {
    if (cptr.ld1so(cptr.ldPtro(mtmp, $monst_data), $permonst_mlet) == NHC.S_GOLEM) {
        /* it's a golem, and not a stone golem */
        if (canseemon(mtmp))
            (yield* pline_mon(mtmp, __s_s_solidifies, (yield* Monnam(mtmp))));
        if ((yield* newcham(mtmp, cptr.add(mons, NHC.PM_STONE_GOLEM, $sizeof_permonst), NHM.NO_NC_FLAGS))) {
            if (canseemon(mtmp))
                (yield* pline(__s_now_it_s_s, (yield* an(pmname(cptr.ldPtro(mtmp, $monst_data), Mgender(mtmp))))));
        } else {
            if (canseemon(mtmp))
                (yield* pline(__s_and_returns_to_normal));
        }
    } else
        (yield* impossible$pline(__s_can_t_polystone_s, (yield* a_monnam(mtmp))));
}

/** C ref: mon.c:3766 — @param {CPtr<struct monst>} mtmp @returns {CInt} */
function* vamp_stone(mtmp) {
    if (is_vampshifter(mtmp)) {
        let mndx = cptr.ldI16o(mtmp, $monst_cham);
        let x = cptr.ldI16o(mtmp, $monst_mx);
        let y = cptr.ldI16o(mtmp, $monst_my);

        /* this only happens if shapeshifted */
        if (mndx >= NHC.LOW_PM &&
                mndx != (cptr.ldI32o((cptr.ldPtro(mtmp, $monst_data)), $permonst_pmidx)) &&
                !(cptr.ld1uo2(
                    svm,
                    mndx,
                    $sizeof_mvitals,
                    $instance_globals_saved_m_mvitals + $mvitals_mvflags
                ) &
                    NHM.G_GENOD)) {
            let buf = new Uint8Array(256);

            /* construct a format string before transformation */
            void cptr.sprintf(
                cptr.decay(buf),
                __s_the_lapidifying_s_s_s,
                (yield* x_monnam(mtmp, NHM.ARTICLE_NONE, null, 15, 0)),
                ((cptr.ldU64o((cptr.ldPtro(mtmp, $monst_data)), $permonst_mflags1) & 4n) != 0n)
                    ? __s_coalesces_on_the
                    : (((cptr.ldU64o((cptr.ldPtro(mtmp, $monst_data)), $permonst_mflags1) &
                        1n) != 0n)
                        ? __s_drops_to_the
                        : __s_writhes_on_the),
                surface(x, y)
            );
            cptr.stI32o(mtmp, $monst_mcanmove, 1);
            cptr.stI32o(mtmp, $monst_mfrozen, 0);
            set_mon_min_mhpmax(mtmp, 10);  /* mtmp->mhpmax=max(m_lev+1,10) */
            cptr.stI32o(mtmp, $monst_mhp, cptr.ldI32o(mtmp, $monst_mhpmax));
            /* this can happen if previously a fog cloud */
            if (((cptr.ldI32o(u, $you_uswallow) & 1) | 0 &&
                    (cptr.eq(cptr.ldPtro(u, $you_ustuck), (mtmp)))))
                (yield* expels(mtmp, cptr.ldPtro(mtmp, $monst_data), 0));
            if (((cptr.ldU64o((cptr.ldPtro(mtmp, $monst_data)), $permonst_mflags1) & 4n) != 0n) &&
                    closed_door(cptr.ldI16o(mtmp, $monst_mx), cptr.ldI16o(mtmp, $monst_my))) {
                let new_xy = cptr.alloc(4);

                if ((yield* enexto(
                    new_xy,
                    cptr.ldI16o(mtmp, $monst_mx),
                    cptr.ldI16o(mtmp, $monst_my),
                    cptr.add(mons, mndx, $sizeof_permonst)
                ))) {
                    (yield* rloc_to(mtmp, cptr.ldI16(new_xy), cptr.ldI16o(new_xy, $nhcoord_y)));
                }
            }
            if (canspotmon(mtmp)) {
                (yield* pline_mon(mtmp, __s_pct_s_bang$mon, cptr.decay(buf)));
                (yield* Y.icall(display_nhwindow()(WIN_MESSAGE.v, 0)));
            }
            void (yield* newcham(mtmp, cptr.add(mons, mndx, $sizeof_permonst), NHM.NO_NC_FLAGS));
            if (cptr.eq(cptr.ldPtro(mtmp, $monst_data), cptr.add(mons, mndx, $sizeof_permonst)))
                cptr.stI16o(mtmp, $monst_cham, NHC.NON_PM);
            else
                cptr.stI16o(mtmp, $monst_cham, i16(mndx));
            if (canspotmon(mtmp)) {
                (yield* pline_mon(
                    mtmp,
                    __s_s_rises_from_the_s_with_renewed_agility,
                    (yield* Amonnam(mtmp)),
                    surface(cptr.ldI16o(mtmp, $monst_mx), cptr.ldI16o(mtmp, $monst_my))
                ));
            }
            (yield* newsym(cptr.ldI16o(mtmp, $monst_mx), cptr.ldI16o(mtmp, $monst_my)));
            return 0;  /* didn't petrify */
        }
    } else if (ismnum(cptr.ldI16o(mtmp, $monst_cham)) &&
            (cptr.ld1uo2(
                mons,
                cptr.ldI16o(mtmp, $monst_cham),
                $sizeof_permonst,
                $permonst_mresists
            ) &
                NHM.MR_STONE)) {
        /* sandestins are stoning-immune so if hit by stoning damage
           they revert to innate shape rather than become a statue */
        cptr.stI32o(mtmp, $monst_mcanmove, 1);
        cptr.stI32o(mtmp, $monst_mfrozen, 0);
        set_mon_min_mhpmax(mtmp, 10);  /* mtmp->mhpmax=max(mtmp->m_lev+1,10) */
        cptr.stI32o(mtmp, $monst_mhp, cptr.ldI32o(mtmp, $monst_mhpmax));
        void (yield* newcham(
            mtmp,
            cptr.add(mons, cptr.ldI16o(mtmp, $monst_cham), $sizeof_permonst),
            NHM.NC_SHOW_MSG
        ));
        (yield* newsym(cptr.ldI16o(mtmp, $monst_mx), cptr.ldI16o(mtmp, $monst_my)));
        return 0;  /* didn't petrify */
    }
    return 1;
}

/* drop monster into "limbo" - that is, migrate to the current level */
/** C ref: mon.c:3834 — @param {CPtr<struct monst>} mtmp */
function* m_into_limbo(mtmp) {
    let target_lev = ledger_no(cptr.add(u, $you_uz));
    let xyloc = NHM.MIGR_APPROX_XY;

    cptr.stI64o(mtmp, $monst_mstate, cptr.ldI64o(mtmp, $monst_mstate) | 8n);
    (yield* migrate_mon(mtmp, target_lev, xyloc));
}

/**
 * C ref: mon.c:3843
 * @param {CPtr<struct monst>} mtmp
 * @param {CInt} target_lev
 * @param {CInt} xyloc
 */
function* migrate_mon(mtmp, target_lev, xyloc) {
    /*
     * If mtmp->mx is zero, this was a failed arrival attempt from a
     * prior migration and mtmp isn't on the map.  In that situation
     * it can't be engulfing or holding the hero or held by same and
     * should have dropped any special objects during that earlier
     * migration back when it had a valid map location.  So only
     * perform some actions when mx is non-zero.
     */
    if (cptr.ldI16o(mtmp, $monst_mx)) {
        (yield* unstuck(mtmp));
        (yield* mdrop_special_objs(mtmp));
    }
    (yield* migrate_to_level(mtmp, target_lev, xyloc, null));
}

/** C ref: mon.c:3864 — @param {CPtr<struct monst>} mtmp @returns {CInt} */
function ok_to_obliterate(mtmp) {
    /*
     * Add checks for monsters that should not be obliterated
     * here (return FALSE).
     */
    if (cptr.eq(
        cptr.ldPtro(mtmp, $monst_data),
        cptr.add(mons, NHC.PM_WIZARD_OF_YENDOR, $sizeof_permonst)
    ) ||
            is_rider(cptr.ldPtro(mtmp, $monst_data)) ||
            has_emin(mtmp) ||
            has_epri(mtmp) ||
            has_eshk(mtmp) ||
            cptr.eq(mtmp, cptr.ldPtro(u, $you_ustuck)) ||
            cptr.eq(mtmp, cptr.ldPtro(u, $you_usteed)))
        return 0;
    return 1;
}

