                mndx = ((rn2(((NHC.PM_APPRENTICE - NHC.PM_STUDENT + 1) | 0)) + NHC.PM_STUDENT) | 0);
                /* avoid own role's guardian */
                if (mndx == cptr.ldI16o(gu, $instance_globals_u_urole + $Role_guardnum))
                    mndx = NHC.NON_PM;
