/**
 * C ref: shk.c:4319
 * @param {CPtr<struct obj>} obj
 * @param {CInt} shk_buying
 * @returns {CLongLong}
 */
function* getprice(obj, shk_buying) {
    let tmp = BigInt(cptr.ldI16o2(
        objects,
        cptr.ldI16o(obj, $obj_otyp),
        $sizeof_objclass,
        $objclass_oc_cost
    ));

    if (cptr.ld1so(obj, $obj_oartifact)) {
        tmp = arti_cost(obj);
        if (shk_buying)
            tmp /= 4n;
    }
    switch (cptr.ld1so(obj, $obj_oclass)) {
        case NHC.FOOD_CLASS:
            tmp += (yield* corpsenm_price_adj(obj));

            /* simpler hunger check, (2-4)*cost */
            if (cptr.ldI32o(u, $you_uhs) >= NHC.HUNGRY && !shk_buying)
                tmp *= BigInt(cptr.ldI32o(u, $you_uhs) >>> 0);
            if (cptr.ldI32o(obj, $obj_oeaten))
                tmp = 0n;
            break;
        case NHC.WAND_CLASS:
            if (cptr.ld1so(obj, $obj_spe) == -1)
                tmp = 0n;
            break;
        case NHC.POTION_CLASS:
            if (cptr.ldI16o(obj, $obj_otyp) == NHC.POT_WATER &&
                    !(cptr.ldI32o(obj, $obj_blessed) & 1) &&
                    !(cptr.ldI32o(obj, $obj_cursed) & 1))
                tmp = 0n;
            break;
        case NHC.ARMOR_CLASS:
        case NHC.WEAPON_CLASS:
            if (cptr.ld1so(obj, $obj_spe) > 0)
                tmp += BigInt.asIntN(64, 10n * BigInt(cptr.ld1so(obj, $obj_spe)));
            break;
        case NHC.TOOL_CLASS:
            if (Is_candle(obj) &&
                    cptr.ldI64o(obj, $obj_age) <
                        BigInt.asIntN(
                            64,
                            20n *
                                BigInt(cptr.ldI16o2(
                                    objects,
                                    cptr.ldI16o(obj, $obj_otyp),
                                    $sizeof_objclass,
                                    $objclass_oc_cost
                                ))
                        ))
                tmp /= 2n;
            break;
    }
    return tmp;
}

