/* called by dotalk(sounds.c) when #chatting; returns obj if location
   contains shop goods and shopkeeper is willing & able to speak */
/** C ref: shk.c:5386 — @param {CInt} x @param {CInt} y @returns {CPtr<struct obj>} */
function* shop_object(x, y) {
    let otmp;
    let shkp;

    shkp = (yield* shop_keeper(cptr.ld1s((yield* in_rooms(x, y, NHC.SHOPBASE)))));
    if (!shkp || !(yield* inhishop(shkp)))
        return null;

    for (
        otmp = cptr.ldPtro3(svl, x, 168, y, 8, $instance_globals_saved_l_level + $dlevel_t_objects);
        otmp;
        otmp = cptr.ldPtro(otmp, $obj_v)
    )
        if (cptr.ld1so(otmp, $obj_oclass) != NHC.COIN_CLASS)
            break;
    /* note: otmp might have ->no_charge set, but that's ok */
    return (otmp &&
        (yield* costly_spot(x, y)) &&
        ((cptr.ldI32o((shkp), $monst_mpeaceful) & 1)) | 0 &&
        !(helpless(shkp) ||
            cptr.ld1uo(cptr.ldPtro((shkp), $monst_data), $permonst_msound) <= NHC.MS_ANIMAL))
            ? otmp
            : null;
}

/* give price quotes for all objects linked to this one (ie, on this spot) */
/** C ref: shk.c:5406 — @param {CPtr<struct obj>} first_obj */
function* price_quote(first_obj) {
    let otmp;
    let buf = new Uint8Array(256);
    let price = new Uint8Array(40);
    let cost = 0n;
    let cnt = 0;
    let contentsonly = 0;
    let tmpwin;
    let shkp;

    shkp = (yield* shop_keeper(inside_shop(cptr.ldI16(u), cptr.ldI16o(u, $you_uy))));
    /* caller has verified that there is a shopkeeper, but the static
       analyzer doesn't realize it */
    if (!shkp || !(yield* inhishop(shkp)))
        return;

    tmpwin = (yield* Y.icall(create_nhwindow()(NHM.NHW_MENU)));
    (yield* Y.icall(putstr()(tmpwin, 0, __s_fine_goods_for_sale)));
    (yield* Y.icall(putstr()(tmpwin, 0, __s_empty$shk)));
    for (otmp = first_obj; otmp; otmp = cptr.ldPtro(otmp, $obj_v)) {
        if (cptr.ld1so(otmp, $obj_oclass) == NHC.COIN_CLASS)
            continue;
        cost = ((cptr.ldI32o(otmp, $obj_no_charge) & 1) | 0 ||
            cptr.eq(otmp, uball.v) ||
            cptr.eq(otmp, uchain.v))
                ? 0n
                : (yield* get_cost(otmp, shkp));
        contentsonly = schar((!cost));
        if ((cptr.ldPtro((otmp), $obj_cobj) !== null))
            cost += (yield* contained_cost(otmp, shkp, 0n, 0, 0));
        if ((cptr.ldI32o(otmp, $obj_globby) & 1))
            cost *= (yield* get_pricing_units(otmp));  /* always quan 1, vary by wt */
        if (!cost) {
            void cptr.strcpy(cptr.decay(price), __s_no_charge$shk);
            contentsonly = 0;
        } else {
            void cptr.sprintf(
                cptr.decay(price),
                __s_ld_s_s,
                cost,
                (yield* currency(cost)),
                (cptr.ldI64o(otmp, $obj_quan)) > 1n ? __s_each : __s_empty$shk
            );
        }
        void cptr.sprintf(
            cptr.decay(buf),
            __s_s_s_s$shk,
            contentsonly ? cptr.decay(the_contents_of) : __s_empty$shk,
            (yield* doname(otmp)),
            cptr.decay(price)
        );
        (yield* Y.icall(putstr()(tmpwin, 0, cptr.decay(buf)))), cnt++;
    }
    if (cnt > 1) {
        (yield* Y.icall(display_nhwindow()(tmpwin, 1)));
    } else if (cnt == 1) {
        if (!cost) {
            /* "<doname(obj)>, no charge" */
            ;
            (yield* verbalize(__s_pct_s_bang$shk, upstart(cptr.decay(buf))));  /* buf contains the string */
        } else {
            /* print cost in slightly different format, so can't reuse buf;
               cost and contentsonly are already set up */
            void cptr.sprintf(
                cptr.decay(buf),
                __s_s_s__3$shk,
                contentsonly ? cptr.decay(the_contents_of) : __s_empty$shk,
                (yield* doname(first_obj))
            );
            ;
            (yield* verbalize(
                __s_s_price_ld_s_s_s,
                upstart(cptr.decay(buf)),
                cost,
                (yield* currency(cost)),
                (cptr.ldI64o(first_obj, $obj_quan) > 1n) ? __s_each : __s_empty$shk,
                contentsonly ? __s_dot$shk : shk_embellish(first_obj, cost)
            ));
        }
    }
    (yield* Y.icall(destroy_nhwindow()(tmpwin)));
}

/**
 * C ref: shk.c:5468
 * @param {CPtr<struct obj>} itm
 * @param {CLongLong} cost
 * @returns {CPtr<char>}
 */
function shk_embellish(itm, cost) {
    if (!rn2(3)) {
        let o;
        let choice = rn2(5);

        if (choice == 0)
            choice = (cost < 100n ? 1 : (cost < 500n ? 2 : 3));
        switch (choice) {
            case 4:
                if (cost < 10n)
                    break;
                else
                    o = cptr.ld1so(itm, $obj_oclass);
                if (o == NHC.FOOD_CLASS)
                    return __s_gourmets_delight;
                if ((cptr.ldI32o2(
                    objects,
                    cptr.ldI16o(itm, $obj_otyp),
                    $sizeof_objclass,
                    $objclass_oc_name_known
                ) & 1) | 0
                        ? (cptr.ldI32o2(
                            objects,
                            cptr.ldI16o(itm, $obj_otyp),
                            $sizeof_objclass,
                            $objclass_oc_magic
                        ) & 1) | 0
                        : (o == NHC.AMULET_CLASS ||
                            o == NHC.RING_CLASS ||
                            o == NHC.WAND_CLASS ||
                            o == NHC.POTION_CLASS ||
                            o == NHC.SCROLL_CLASS ||
                            o == NHC.SPBOOK_CLASS
                            ? 1
                            : 0))
                    return __s_painstakingly_developed;
                return __s_superb_craftsmanship;
            case 3:
                return __s_finest_quality;
            case 2:
                return __s_an_excellent_choice;
            case 1:
                return __s_a_real_bargain;
            default:
                break;
        }
    } else if (cptr.ld1so(itm, $obj_oartifact)) {
        return __s_one_of_a_kind;
    }
    return __s_dot$shk;
}

