/* Save the dungeon structures. */
/**
 * C ref: dungeon.c:149
 * @param {CPtr<NHFILE>} nhfp
 * @param {CInt} perform_write
 * @param {CInt} free_data
 */
function* save_dungeon(nhfp, perform_write, free_data) {
    let i;
    let count = cptr.box(0);
    let curr;
    let next;
    let curr_ms;
    let next_ms;

    if (perform_write) {
        (yield* sfo_int(nhfp, svn, __s_dungeon_count));
        for (i = 0; i < cptr.ldI32(svn); ++i) {
            (yield* sfo_dungeon(nhfp, cptr.add(svd, i, $sizeof_dungeon), __s_dungeon$dungeon));
        }
        (yield* sfo_dgn_topology(
            nhfp,
            cptr.add(svd, $instance_globals_saved_d_dungeon_topology),
            __s_svd_dungeon_topology
        ));
        (yield* sfo_char(nhfp, svt, __s_tune, 6));
        for (count.v = 0, curr = cptr.ldPtr(svb); curr; curr = cptr.ldPtr(curr))
            count.v++;
        (yield* sfo_int(nhfp, count, __s_branch_count));

        for (curr = cptr.ldPtr(svb); curr; curr = cptr.ldPtr(curr)) {
            (yield* sfo_branch(nhfp, curr, __s_branch$dungeon));
        }
        count.v = maxledgerno();
        (yield* sfo_int(nhfp, count, __s_level_info_count));
        for (i = 0; i < count.v; ++i) {
            (yield* sfo_linfo(
                nhfp,
                cptr.add(cptr.add(svl, $instance_globals_saved_l_level_info), i, $sizeof_linfo),
                __s_svl_level_info
            ));
        }
        (yield* sfo_nhcoord(nhfp, svi, __s_svi_inv_pos));

        for (count.v = 0, curr_ms = cptr.ldPtr(svm); curr_ms; curr_ms = cptr.ldPtr(curr_ms))
            count.v++;

        (yield* sfo_int(nhfp, count, __s_mapseen_count));

        for (curr_ms = cptr.ldPtr(svm); curr_ms; curr_ms = cptr.ldPtr(curr_ms)) {
            (yield* save_mapseen(nhfp, curr_ms));
        }
    }

    if (free_data) {
        for (curr = cptr.ldPtr(svb); curr; curr = next) {
            next = cptr.ldPtr(curr);
            cptr.free(curr);
        }
        cptr.stPtr(svb, null);
        for (curr_ms = cptr.ldPtr(svm); curr_ms; curr_ms = next_ms) {
            next_ms = cptr.ldPtr(curr_ms);
            if (cptr.ldPtro(curr_ms, $mapseen_custom))
                cptr.free(cptr.ldPtro(curr_ms, $mapseen_custom));
            if (cptr.ldPtro(curr_ms, $mapseen_final_resting_place))
                (yield* savecemetery(nhfp, cptr.add(curr_ms, $mapseen_final_resting_place)));
            cptr.free(curr_ms);
        }
        cptr.stPtr(svm, null);
    }
}

/* Restore the dungeon structures. */
/** C ref: dungeon.c:211 — @param {CPtr<NHFILE>} nhfp */
function* restore_dungeon(nhfp) {
    let curr;
    let last;
    let count = cptr.box(0);
    let i;
    let curr_ms;
    let last_ms;

    (yield* sfi_int(nhfp, svn, __s_dungeon_count));
    ;
    for (i = 0; i < cptr.ldI32(svn); ++i) {
        (yield* sfi_dungeon(nhfp, cptr.add(svd, i, $sizeof_dungeon), __s_dungeon$dungeon));
    }
    (yield* sfi_dgn_topology(
        nhfp,
        cptr.add(svd, $instance_globals_saved_d_dungeon_topology),
        __s_svd_dungeon_topology
    ));
    (yield* sfi_char(nhfp, svt, __s_tune, 6));

    last = cptr.stPtr(svb, null);

    (yield* sfi_int(nhfp, count, __s_branch_count));
    ;

    for (i = 0; i < count.v; i++) {
        curr = (yield* alloc(32));
        (yield* sfi_branch(nhfp, curr, __s_branch$dungeon));
        cptr.stPtr(curr, null);
        if (last)
            cptr.stPtr(last, curr);
        else
            cptr.stPtr(svb, curr);
        last = curr;
    }

    (yield* sfi_int(nhfp, count, __s_level_info_count));
    ;

    if (count.v >= 512)
        (yield* panic$end(__s_level_information_count_larger_d_than, count.v));
    for (i = 0; i < count.v; ++i) {
        (yield* sfi_linfo(
            nhfp,
            cptr.add(cptr.add(svl, $instance_globals_saved_l_level_info), i, $sizeof_linfo),
            __s_svl_level_info
        ));
    }

    (yield* sfi_nhcoord(nhfp, svi, __s_svi_inv_pos));

    (yield* sfi_int(nhfp, count, __s_mapseen_count));
    ;

    last_ms = null;
    for (i = 0; i < count.v; i++) {
        curr_ms = (yield* load_mapseen(nhfp));
        cptr.stPtr(curr_ms, null);
        if (last_ms)
            cptr.stPtr(last_ms, curr_ms);
        else
            cptr.stPtr(svm, curr_ms);
        last_ms = curr_ms;
    }
}

