            (yield* sfo_int16(nhfp, cptr.add(ez, $exclusion_zone_lx), __s_exclusion_lx));
            (yield* sfo_int16(nhfp, cptr.add(ez, $exclusion_zone_ly), __s_exclusion_ly));
