/* Compute the total probability of each object class.
 * Assumes svb.bases[] has already been set. */
/** C ref: o_init.c:240 */
function* init_oclass_probs() {
    let i;
    let sum;
    let oclass;
    for (oclass = 0; oclass < NHC.MAXOCLASSES; ++oclass) {
        sum = 0;
        /* note: for ILLOBJ_CLASS, bases[oclass+1]-1 isn't the last item
           in the class; but all the generic items have probability 0 so
           adding them to 'sum' has no impact */
        for (
            i = cptr.ldI32o2(svb, oclass, 4, $instance_globals_saved_b_bases);
            i < cptr.ldI32o2(svb, (oclass + 1) | 0, 4, $instance_globals_saved_b_bases);
            ++i
        ) {
            sum = i16(sum + cptr.ldI16o2(objects, i, $sizeof_objclass, $objclass_oc_prob));
        }
        if (sum <= 0 &&
                oclass != NHC.ILLOBJ_CLASS &&
                cptr.ldI32o2(svb, oclass, 4, $instance_globals_saved_b_bases) !=
                    cptr.ldI32o2(svb, (oclass + 1) | 0, 4, $instance_globals_saved_b_bases)) {
            (yield* impossible$pline(
                __s_s_d_probability_total_for_oclass_d,
                !sum ? __s_zero$o_init : __s_negative$o_init,
                sum,
                oclass
            ));
            /* gracefully fail by setting all members of this class to 1 */
            for (
                i = cptr.ldI32o2(svb, oclass, 4, $instance_globals_saved_b_bases);
                i < cptr.ldI32o2(svb, (oclass + 1) | 0, 4, $instance_globals_saved_b_bases);
                ++i
            ) {
                cptr.stI16o2(objects, i, $sizeof_objclass, $objclass_oc_prob, 1);
                sum++;
            }
        }
        cptr.stI16o2(go, oclass, 2, $instance_globals_o_oclass_prob_totals, sum);
    }
}

/* retrieve the range of objects that otyp shares descriptions with */
/** C ref: o_init.c:269 — @param {CInt} otyp @param {CPtr<int>} lo_p @param {CPtr<int>} hi_p */
function obj_shuffle_range(otyp, lo_p, hi_p) {
    let i;
    let ocls = cptr.ld1so2(objects, otyp, $sizeof_objclass, $objclass_oc_class);

    /* default is just the object itself */
    cptr.stI32(lo_p, cptr.stI32(hi_p, otyp));

    switch (ocls) {
        case NHC.ARMOR_CLASS:
            if (otyp >= NHC.HELMET && otyp <= NHC.HELM_OF_TELEPATHY)
                cptr.stI32(lo_p, NHC.HELMET), cptr.stI32(hi_p, NHC.HELM_OF_TELEPATHY);
            else if (otyp >= NHC.LEATHER_GLOVES && otyp <= NHC.GAUNTLETS_OF_DEXTERITY)
                cptr.stI32(lo_p, NHC.LEATHER_GLOVES), cptr.stI32(hi_p, NHC.GAUNTLETS_OF_DEXTERITY);
            else if (otyp >= NHC.CLOAK_OF_PROTECTION && otyp <= NHC.CLOAK_OF_DISPLACEMENT)
                cptr.stI32(lo_p, NHC.CLOAK_OF_PROTECTION),
                        cptr.stI32(hi_p, NHC.CLOAK_OF_DISPLACEMENT);
            else if (otyp >= NHC.SPEED_BOOTS && otyp <= NHC.LEVITATION_BOOTS)
                cptr.stI32(lo_p, NHC.SPEED_BOOTS), cptr.stI32(hi_p, NHC.LEVITATION_BOOTS);
            break;
        case NHC.POTION_CLASS:
            /* potion of water has the only fixed description */
            cptr.stI32(
                lo_p,
                cptr.ldI32o2(svb, NHC.POTION_CLASS, 4, $instance_globals_saved_b_bases)
            );
            cptr.stI32(hi_p, ((NHC.POT_WATER - 1) | 0));
            break;
        case NHC.AMULET_CLASS:
        case NHC.SCROLL_CLASS:
        case NHC.SPBOOK_CLASS:
            /* exclude non-magic types and also unique ones */
            cptr.stI32(lo_p, cptr.ldI32o2(svb, ocls, 4, $instance_globals_saved_b_bases));
            for (
                i = cptr.ldI32(lo_p);
                cptr.ld1so2(objects, i, $sizeof_objclass, $objclass_oc_class) == ocls;
                i++
            )
                if ((cptr.ldI32o2(objects, i, $sizeof_objclass, $objclass_oc_unique) & 1) | 0 ||
                        !(cptr.ldI32o2(objects, i, $sizeof_objclass, $objclass_oc_magic) & 1))
                    break;
            cptr.stI32(hi_p, (i - 1) | 0);
            break;
        case NHC.RING_CLASS:
        case NHC.WAND_CLASS:
        case NHC.VENOM_CLASS:
            /* entire class */
            cptr.stI32(lo_p, cptr.ldI32o2(svb, ocls, 4, $instance_globals_saved_b_bases));
            cptr.stI32(
                hi_p,
                (cptr.ldI32o2(svb, (ocls + 1) | 0, 4, $instance_globals_saved_b_bases) - 1) | 0
            );
            break;
    }

    /* artifact checking might ask about item which isn't part of any range
       but fell within the classes that do have ranges specified above */
    if (otyp < cptr.ldI32(lo_p) || otyp > cptr.ldI32(hi_p))
        cptr.stI32(lo_p, cptr.stI32(hi_p, otyp));
    return;
}

/* randomize object descriptions */
const __static_shuffle_all_shuffle_classes = [
    NHC.AMULET_CLASS,
    NHC.POTION_CLASS,
    NHC.RING_CLASS,
    NHC.SCROLL_CLASS,
    NHC.SPBOOK_CLASS,
    NHC.WAND_CLASS,
    NHC.VENOM_CLASS
]; /** C ref: o_init.c:325 — char[7] (function-static) */
const __static_shuffle_all_shuffle_types = cptr.alloc(4 * 2);
cptr.stI16o(__static_shuffle_all_shuffle_types, 0, NHC.HELMET);
cptr.stI16o(__static_shuffle_all_shuffle_types, 2, NHC.LEATHER_GLOVES);
cptr.stI16o(__static_shuffle_all_shuffle_types, 4, NHC.CLOAK_OF_PROTECTION);
cptr.stI16o(__static_shuffle_all_shuffle_types, 6, NHC.SPEED_BOOTS); /** C ref: o_init.c:330 — short[4] (function-static) */

/** C ref: o_init.c:322 */
function shuffle_all() {
    let first = cptr.box(0);
    let last = cptr.box(0);
    let idx;

    /* do whole classes (amulets, &c) */
    for (idx = 0; idx < __static_shuffle_all_shuffle_classes.length; idx++) {
        obj_shuffle_range(
            cptr.ldI32o2(
                svb,
                cptr.ld1so(cptr.decay(__static_shuffle_all_shuffle_classes), idx, 1),
                4,
                $instance_globals_saved_b_bases
            ),
            first,
            last
        );
        shuffle(first.v, last.v, 1);
    }
    /* do type ranges (helms, &c) */
    for (idx = 0; idx < 4; idx++) {
        obj_shuffle_range(cptr.ldI16o(__static_shuffle_all_shuffle_types, idx, 2), first, last);
        shuffle(first.v, last.v, 0);
    }
    return;
}

/* Return TRUE if the provided string matches the unidentified description of
 * the provided object. */
/** C ref: o_init.c:352 — @param {CPtr<struct obj>} obj @param {CPtr<char>} descr @returns {CInt} */
function* objdescr_is(obj, descr) {
    let objdescr;

    if (!obj) {
        (yield* impossible$pline(__s_objdescr_is_null_obj));
        return 0;
    }

    objdescr = (cptr.ldPtro2(
        obj_descr,
        cptr.ldI16o(
            (cptr.add(objects, cptr.ldI16o(obj, $obj_otyp), $sizeof_objclass)),
            $objclass_oc_descr_idx
        ),
        $sizeof_objdescr,
        $objdescr_oc_descr
    ));
    if (!objdescr)
        return 0;  /* no obj description, no match */
    return schar((!strcmp(objdescr, descr)));
}

