/* light damages hero in gremlin form */
/**
 * C ref: zap.c:3026
 * @param {CPtr<struct obj>} obj
 * @param {CInt} ordinary
 * @param {CInt} amt
 * @returns {CInt}
 */
function* lightdamage(obj, ordinary, amt) {
    let buf = new Uint8Array(256);
    let how;
    let dmg = amt;

    if (dmg &&
            cptr.eq(
                cptr.ldPtro(gy, $instance_globals_y_youmonst + $monst_data),
                cptr.add(mons, NHC.PM_GREMLIN, $sizeof_permonst)
            )) {
        /* reduce high values (from destruction of wand with many charges) */
        dmg = rnd(dmg);
        if (dmg > 10)
            dmg = (10 + rnd((dmg - 10) | 0)) | 0;
        if (dmg > 20)
            dmg = 20;
        (yield* pline(__s_ow_that_light_hurts_c, (dmg > 2 || cptr.ldI32o(u, $you_mh) <= 5) ? 33 : 46));
        /* [composing killer/reason is superfluous here; if fatal, cause
           of death will always be "killed while stuck in creature form"] */
        if (cptr.ld1so(obj, $obj_oclass) == NHC.SCROLL_CLASS ||
                cptr.ld1so(obj, $obj_oclass) == NHC.SPBOOK_CLASS)
            ordinary = 0;  /* say blasted rather than zapped */
        how = (cptr.ld1so(obj, $obj_oclass) == NHC.SPBOOK_CLASS)
                ? __s_spell_of_light
                : ((!cptr.ld1so(obj, $obj_oartifact))
                    ? (yield* ansimpleoname(obj))
                    : (yield* bare_artifactname(obj)));
        void cptr.sprintf(
            cptr.decay(buf),
            __s_s_sself_with_s,
            ordinary ? __s_zapped : __s_blasted,
            (cptr.ldPtro2(
                genders,
                cptr.ld1so(flags, $flag_female) ? 1 : 0,
                $sizeof_Gender,
                $Gender_him
            )),
            how
        );
        /* might rehumanize(); could be fatal, but only for Unchanging */
        (yield* losehp(
            ((Half_physical_damage()) ? (((((dmg) + 1) | 0) / 2) | 0) : (dmg)),
            cptr.decay(buf),
            NHM.NO_KILLER_PREFIX
        ));
    }
    return dmg;
}

/* light[ning] causes blindness */
/** C ref: zap.c:3060 — @param {CLongLong} duration @param {CInt} via_lightning @returns {CInt} */
function* flashburn(duration, via_lightning) {
    if (!(yield* resists_blnd(cptr.add(gy, $instance_globals_y_youmonst)))) {
        (yield* You(cptr.decay(are_blinded_by_the_flash)));
        (yield* make_blinded(duration, 0));
        if (!Blind())
            (yield* Your(__s_pct_s$zap, cptr.ldPtro(c_common_strings, $c_common_strings_c_vision_clears)));
        return 1;
    }
    /* if blinding is resisted due to magical equipment (Sunsword), give
       a sparkle animation (even if also resisted due to being blind)
       _unless_ this is lightning-induced; we don't want a double sparkle
       if hero is both lightning resistant and blindness resistant, or
       worse, have a single sparkle where the player confuses blindness
       resistance for lightning resistance */
    if (!via_lightning && resists_blnd_by_arti(cptr.add(gy, $instance_globals_y_youmonst))) {
        (yield* shieldeff(cptr.ldI16(u), cptr.ldI16o(u, $you_uy)));
        return 1;
    }
    return 0;
}

/* you've zapped a wand downwards while riding
 * Return TRUE if the steed was hit by the wand.
 * Return FALSE if the steed was not hit by the wand.
 */
/** C ref: zap.c:3087 — @param {CPtr<struct obj>} obj @returns {CInt} */
function* zap_steed(obj) {
    let steedhit = 0;

    cptr.stI16o(
        gb,
        $instance_globals_b_bhitpos,
        cptr.ldI16o(cptr.ldPtro(u, $you_usteed), $monst_mx)
    ),
            cptr.stI16o(
                gb,
                $instance_globals_b_bhitpos + $nhcoord_y,
                cptr.ldI16o(cptr.ldPtro(u, $you_usteed), $monst_my)
            );
    cptr.st1o(gn, $instance_globals_n_notonhead, 0);
    switch (cptr.ldI16o(obj, $obj_otyp)) {
        case NHC.WAN_PROBING:
            (yield* probe_monster(cptr.ldPtro(u, $you_usteed)));
            (yield* learnwand(obj));
            steedhit = 1;
            break;
        case NHC.WAN_TELEPORTATION:
        case NHC.SPE_TELEPORT_AWAY:
            /* you go together */
            (yield* tele());
            /* same criteria as when unmounted (zapyourself) */
            if ((Teleport_control() && !HStun()) ||
                    !((cptr.ld1uo(
                        cptr.ldPtro(
                            cptr.ldPtro(gv, $instance_globals_v_viz_array),
                            cptr.ldI16o(u, $you_uy0),
                            8
                        ),
                        cptr.ldI16o(u, $you_ux0)
                    ) &
                        NHM.COULD_SEE) !=
                        0) ||
                    dist2(
                        (cptr.ldI16o(u, $you_ux0)),
                        (cptr.ldI16o(u, $you_uy0)),
                        cptr.ldI16(u),
                        cptr.ldI16o(u, $you_uy)
                    ) >= 16)
                (yield* learnwand(obj));
            steedhit = 1;
            break;
        case NHC.SPE_CURE_SICKNESS:
        case NHC.WAN_MAKE_INVISIBLE:
        case NHC.WAN_CANCELLATION:
        case NHC.SPE_CANCELLATION:
        case NHC.WAN_POLYMORPH:
        case NHC.SPE_POLYMORPH:
        case NHC.WAN_STRIKING:
        case NHC.SPE_FORCE_BOLT:
        case NHC.WAN_SLOW_MONSTER:
        case NHC.SPE_SLOW_MONSTER:
        case NHC.WAN_SPEED_MONSTER:
        case NHC.SPE_HEALING:
        case NHC.SPE_EXTRA_HEALING:
        case NHC.SPE_DRAIN_LIFE:
        case NHC.WAN_OPENING:
        case NHC.SPE_KNOCK:
            void (yield* bhitm(cptr.ldPtro(u, $you_usteed), obj));
            steedhit = 1;
            break;
        default:
            steedhit = 0;
            break;
    }
    return schar(steedhit);
}

/*
 * cancel a monster (possibly the hero).  inventory is cancelled only
 * if the monster is zapping itself directly, since otherwise the
 * effect is too strong.  currently non-hero monsters do not zap
 * themselves with cancellation.
 */
const __static_cancel_monst_writing_vanishes = cptr.bytes("Some writing vanishes from %s head!"); /** C ref: zap.c:3154 — char[36] (function-static) */
const __static_cancel_monst_your = cptr.bytes("your"); /** C ref: zap.c:3155 — char[5] (function-static) */

/**
 * C ref: zap.c:3150
 * @param {CPtr<struct monst>} mdef
 * @param {CPtr<struct obj>} obj
 * @param {CInt} youattack
 * @param {CInt} allow_cancel_kill
 * @param {CInt} self_cancel
 * @returns {CInt}
 */
function* cancel_monst(mdef, obj, youattack, allow_cancel_kill, self_cancel) {
    let youdefend = schar((cptr.eq(mdef, cptr.add(gy, $instance_globals_y_youmonst))));

    if (youdefend
            ? (!youattack && Antimagic() ? 1 : 0)
            : (yield* resist(mdef, cptr.ld1so(obj, $obj_oclass), 0, NHM.NOTELL)))
        return 0;  /* resisted cancellation */

    if (self_cancel) {
        let otmp;

        for (
            otmp = (youdefend
                ? cptr.ldPtro(gi, $instance_globals_i_invent)
                : cptr.ldPtro(mdef, $monst_minvent));
            otmp;
            otmp = cptr.ldPtr(otmp)
        )
            (yield* cancel_item(otmp));

        if (youdefend) {
            cptr.st1(disp, 1);  /* potential AC change */
            find_ac();
            /* update_inventory(); -- handled by caller */
        }
    }

    /* now handle special cases */
    if (youdefend) {
        if (Upolyd()) {
            /*
             * Return to normal form unless Unchanging.
             * Hero in clay golem form dies if Unchanging.
             * Does not cure lycanthropy or stop timed random polymorph.
             */
            if (cptr.ldI32o(u, $you_umonnum) == NHC.PM_CLAY_GOLEM) {
                if (!Blind())
                    (yield* pline(
                        cptr.decay(__static_cancel_monst_writing_vanishes),
                        cptr.decay(__static_cancel_monst_your)
                    ));
                else
                    (yield* You_feel(__s_s_headed, Hallucination() ? __s_dark$zap : __s_light$zap));
                cptr.stI32o(u, $you_mh, 0);  /* fatal; death handled by rehumanize() */
            }
            if (Unchanging() && cptr.ldI32o(u, $you_mh) > 0)
                (yield* Your(__s_amulet_grows_hot_for_a_moment_then_cools));
            else
                (yield* rehumanize());
        }
    } else {
        cptr.stI32o(mdef, $monst_mcan, 1);
        /* force shapeshifter into its base form or mimic to unhide */
        (yield* normal_shape(mdef));

        if (cptr.eq(
            cptr.ldPtro(mdef, $monst_data),
            cptr.add(mons, NHC.PM_CLAY_GOLEM, $sizeof_permonst)
        )) {
            if (canseemon(mdef))
                (yield* pline(cptr.decay(__static_cancel_monst_writing_vanishes), (yield* s_suffix((yield* mon_nam(mdef))))));
            /* !allow_cancel_kill is for Magicbane, where clay golem
               will be killed somewhere back up the call/return chain... */
            if (allow_cancel_kill) {
                if (youattack)
                    (yield* killed(mdef));
                else
                    (yield* monkilled(mdef, __s_empty$zap, NHM.AD_SPEL));
            }
        }
    }
    return 1;
}

