    /* drawbridge might change <u.ux,u.uy> */
    x = (xx.v = cptr.ldI16(u));  /* <x,y> is zap location */
    y = (yy.v = cptr.ldI16o(u, $you_uy));  /* <xx,yy> is drawbridge (portcullis) position */
    ttmp = t_at(x, y);  /* trap if there is one */

