        cptr.stPtr(d, (yield* mksobj(NHC.GOLD_PIECE, 0, 0)));
        cptr.stI64o(cptr.ldPtr(d), $obj_quan, BigInt(cptr.ldI32o(d, $_readobjnam_data_cnt)));
        cptr.stI32o(cptr.ldPtr(d), $obj_owt, (yield* weight(cptr.ldPtr(d))) >>> 0);
