/* #monster command - use special monster ability while polymorphed */
/** C ref: cmd.c:890 @returns {CInt} */
function* domonability() {
    let uptr = cptr.ldPtro(gy, $instance_globals_y_youmonst + $monst_data);
    let might_hide = schar((((cptr.ldU64o((uptr), $permonst_mflags1) & 256n) != 0n) ||
        ((cptr.ldU64o((uptr), $permonst_mflags1) & 128n) != 0n)
            ? 1
            : 0));
    let c = 0;

    if (might_hide && webmaker(uptr)) {
        c = (yield* yn_function(__s_hide_h_or_spin_a_web_s, cptr.decay(hidespinchars), 113, 1));
        if (c == 113 || c == 27)
            return NHM.ECMD_OK;
    }
    if (attacktype(uptr, NHM.AT_BREA))
        return (yield* dobreathe());
    else if (attacktype(uptr, NHM.AT_SPIT))
        return (yield* dospit());
    else if (cptr.ld1so(uptr, $permonst_mlet) == NHC.S_NYMPH)
        return (yield* doremove());
    else if (attacktype(uptr, NHM.AT_GAZE))
        return (yield* dogaze());
    else if (((cptr.ldU64o((uptr), $permonst_mflags2) & 4n) != 0n))
        return (yield* dosummon());
    else if (c ? c == 104 : might_hide)
        return (yield* dohide());
    else if (c ? c == 115 : webmaker(uptr))
        return (yield* dospinweb());
    else if (is_mind_flayer(uptr))
        return (yield* domindblast());
    else if (cptr.ldI32o(u, $you_umonnum) == NHC.PM_GREMLIN) {
        if (((cptr.ld1so3(
            svl,
            cptr.ldI16(u),
            $sizeof_rm_x21,
            cptr.ldI16o(u, $you_uy),
            $sizeof_rm,
            $instance_globals_saved_l_level + $rm_typ
        )) ==
                NHC.FOUNTAIN)) {
            if ((yield* split_mon(cptr.add(gy, $instance_globals_y_youmonst), null)))
                (yield* dryup(cptr.ldI16(u), cptr.ldI16o(u, $you_uy), 1));
        } else if (is_pool(cptr.ldI16(u), cptr.ldI16o(u, $you_uy))) {
            /* is_pool: might be wearing water walking boots or amulet of
               magical breathing */
            void (yield* split_mon(cptr.add(gy, $instance_globals_y_youmonst), null));
        } else {
            (yield* There(__s_is_no_fountain_here));
        }
    } else if (is_unicorn(uptr)) {
        (yield* use_unicorn_horn(null));
        return NHM.ECMD_TIME;
    } else if (cptr.ld1uo(uptr, $permonst_msound) == NHC.MS_SHRIEK) {
        (yield* You(__s_shriek$cmd));
        if ((cptr.ldI32o(u, $you_uburied) & 1))
            (yield* pline(__s_unfortunately_sound_does_not_carry_well));
        else
            (yield* aggravate());
    } else if ((cptr.ld1so((uptr), $permonst_mlet) == NHC.S_VAMPIRE) ||
            is_vampshifter(cptr.add(gy, $instance_globals_y_youmonst))) {
        return (yield* dopoly());
    } else if (cptr.ldPtro(u, $you_usteed) &&
            attacktype(cptr.ldPtro(cptr.ldPtro(u, $you_usteed), $monst_data), NHM.AT_BREA)) {
        void (yield* pet_ranged_attk(cptr.ldPtro(u, $you_usteed), 1));
        return NHM.ECMD_TIME;
    } else if (Upolyd()) {
        (yield* pline(__s_any_special_ability_you_may_have_is));
    } else {
        (yield* You(__s_don_t_have_a_special_ability_in_your));
    }
    return NHM.ECMD_OK;
}

/** C ref: cmd.c:952 @returns {CInt} */
function* enter_explore_mode() {
    if (discover()) {
        (yield* You(__s_are_already_in_explore_mode));
    } else {
        let oldmode = !wizard() ? __s_normal_game : __s_debug_mode;

        if (!authorize_explore_mode()) {
            if (!wizard()) {
                (yield* You(__s_cannot_access_explore_mode));
                return NHM.ECMD_OK;
            } else {
                (yield* pline(__s_note_normally_you_wouldn_t_be_allowed));
                /* keep going */
            }
        }
        (yield* pline(__s_beware_from_explore_mode_there_will_be, oldmode));
        if ((yield* paranoid_query(
            schar((((cptr.ldI32o(flags, $flag_paranoia_bits) & NHM.PARANOID_QUIT) >>> 0) != 0)),
            __s_do_you_want_to_enter_explore_mode
        ))) {
            cptr.st1o(flags, $flag_explore, 1);
            cptr.st1o(flags, $flag_debug, 0);
            (yield* Y.icall(clear_nhwindow()(WIN_MESSAGE.v)));
            (yield* You(__s_are_now_in_non_scoring_explore_mode));
        } else {
            (yield* Y.icall(clear_nhwindow()(WIN_MESSAGE.v)));
            (yield* pline(__s_continuing_with_s, oldmode));
        }
    }
    return NHM.ECMD_OK;
}

