/*
 * Creation of a drawbridge at pos x,y.
 *     dir is the direction.
 *     flag must be put to TRUE if we want the drawbridge to be opened.
 */
/**
 * C ref: dbridge.c:235
 * @param {CInt} x
 * @param {CInt} y
 * @param {CInt} dir
 * @param {CInt} flag
 * @returns {CInt}
 */
function* create_drawbridge(x, y, dir, flag) {
    let x2;
    let y2;
    let horiz;
    let lava = schar((cptr.ld1so3(
        svl,
        x,
        $sizeof_rm_x21,
        y,
        $sizeof_rm,
        $instance_globals_saved_l_level + $rm_typ
    ) ==
            NHC.LAVAPOOL));  /* assume initialized map */

    x2 = x;
    y2 = y;
    switch (dir) {
        case NHM.DB_NORTH:
            horiz = 1;
            y2--;
            break;
        case NHM.DB_SOUTH:
            horiz = 1;
            y2++;
            break;
        case NHM.DB_EAST:
            horiz = 0;
            x2++;
            break;
        default:
            (yield* impossible$pline(__s_bad_direction_in_create_drawbridge));
            // @FallThrough
            ;
        case NHM.DB_WEST:
            horiz = 0;
            x2--;
            break;
    }
    if (!((cptr.ld1so3(
        svl,
        x2,
        $sizeof_rm_x21,
        y2,
        $sizeof_rm,
        $instance_globals_saved_l_level + $rm_typ
    )) &&
            (cptr.ld1so3(
                svl,
                x2,
                $sizeof_rm_x21,
                y2,
                $sizeof_rm,
                $instance_globals_saved_l_level + $rm_typ
            )) <=
                NHC.DBWALL))
        return 0;
    if (flag) {
        cptr.st1o3(
            svl,
            x,
            $sizeof_rm_x21,
            y,
            $sizeof_rm,
            $instance_globals_saved_l_level + $rm_typ,
            NHC.DRAWBRIDGE_DOWN
        );
        cptr.st1o3(
            svl,
            x2,
            $sizeof_rm_x21,
            y2,
            $sizeof_rm,
            $instance_globals_saved_l_level + $rm_typ,
            NHC.DOOR
        );
        cptr.stI32o3(
            svl,
            x2,
            $sizeof_rm_x21,
            y2,
            $sizeof_rm,
            $instance_globals_saved_l_level + $rm_flags,
            NHM.D_NODOOR
        );
    } else {
        cptr.st1o3(
            svl,
            x,
            $sizeof_rm_x21,
            y,
            $sizeof_rm,
            $instance_globals_saved_l_level + $rm_typ,
            NHC.DRAWBRIDGE_UP
        );
        cptr.st1o3(
            svl,
            x2,
            $sizeof_rm_x21,
            y2,
            $sizeof_rm,
            $instance_globals_saved_l_level + $rm_typ,
            NHC.DBWALL
        );
        /* Drawbridges are non-diggable. */
        cptr.stI32o3(
            svl,
            x2,
            $sizeof_rm_x21,
            y2,
            $sizeof_rm,
            $instance_globals_saved_l_level + $rm_flags,
            NHM.W_NONDIGGABLE
        );
    }
    cptr.stI32o3(
        svl,
        x,
        $sizeof_rm_x21,
        y,
        $sizeof_rm,
        $instance_globals_saved_l_level + $rm_horizontal,
        (!horiz) >>> 0
    );
    cptr.stI32o3(
        svl,
        x2,
        $sizeof_rm_x21,
        y2,
        $sizeof_rm,
        $instance_globals_saved_l_level + $rm_horizontal,
        horiz
    );
    cptr.stI32o3(
        svl,
        x,
        $sizeof_rm_x21,
        y,
        $sizeof_rm,
        $instance_globals_saved_l_level + $rm_flags,
        dir >>> 0
    );
    if (lava)
        cptr.stI32o3(
            svl,
            x,
            $sizeof_rm_x21,
            y,
            $sizeof_rm,
            $instance_globals_saved_l_level + $rm_flags,
            cptr.ldI32o3(
                svl,
                x,
                $sizeof_rm_x21,
                y,
                $sizeof_rm,
                $instance_globals_saved_l_level + $rm_flags
            ) |
                NHM.DB_LAVA
        );
    return 1;
}

