/*
 * Synch the third screen with the display.
 */
let __static_flush_screen_flushing = 0; /** C ref: display.c:2213 — int (function-static) */
let __static_flush_screen_delay_flushing = 0; /** C ref: display.c:2214 — int (function-static) */

/** C ref: display.c:2208 — @param {CInt} cursor_on_u */
function* flush_screen(cursor_on_u) {
    let x;
    let y;
    let bkglyphinfo = cptr.alloc(48); cptr.memcpy(bkglyphinfo, nul_glyphinfo.v, $sizeof_glyphinfo);
    let bkglyph = cptr.box(0);

    /* 5.0: don't update map, status, or perm_invent during save/restore */
    if ((cptr.ld1so(gi, $instance_globals_i_in_mklev) ||
            cptr.ldI32o(program_state, $sinfo_saving) ||
            cptr.ldI32o(program_state, $sinfo_restoring) ||
            cptr.ldI32o(program_state, $sinfo_done_hup)))
        return;

    if (cursor_on_u == -1)
        __static_flush_screen_delay_flushing = !__static_flush_screen_delay_flushing;
    if (__static_flush_screen_delay_flushing)
        return;
    if (__static_flush_screen_flushing)
        return;  /* if already flushing then return */
    __static_flush_screen_flushing = 1;
    if (cptr.ldI32o(program_state, $sinfo_done_hup))
        return;

    /* get this done now, before we place the cursor on the hero */
    if (cptr.ld1s(disp) || cptr.ld1so(disp, $display_hints_botlx))
        (yield* bot());
    else if (cptr.ld1so(disp, $display_hints_time_botl))
        (yield* timebot());

    for (y = 0; y < NHM.ROWNO; y++) {
        let gptr = cptr.add(
            cptr.add(gg, y, $sizeof_gbuf_entry_x80),
            x = cptr.ldI16o2(gg, y, 2, $instance_globals_g_gbuf_start),
            $sizeof_gbuf_entry
        );

        for (
            ;
            x <= cptr.ldI16o2(gg, y, 2, $instance_globals_g_gbuf_stop);
            gptr = cptr.add(gptr, 1, 56),
            x++
        ) {
            (yield* get_bkglyph_and_framecolor(x, y, bkglyph, cptr.add(bkglyphinfo, $glyphinfo_framecolor)));
            if (cptr.ld1s(gptr) ||
                    (cptr.ldI32o(
                        gw,
                        $instance_globals_w_wsettings + $win_settings_map_frame_color
                    ) !=
                        NHM.NO_COLOR &&
                        cptr.ldI32o(bkglyphinfo, $glyphinfo_framecolor) != NHM.NO_COLOR)) {
                /* map_glyphinfo() won't touch framecolor */
                map_glyphinfo(x, y, bkglyph.v, 0, bkglyphinfo);
                (yield* Y.icall(print_glyph()(
                    WIN_MAP.v,
                    x,
                    y,
                    (((x) < 0 || (y) < 0 || (x) >= NHM.COLNO || (y) >= NHM.ROWNO)
                        ? no_ginfo
                        : cptr.add(
                            cptr.add(
                                cptr.add(gg, (y), $sizeof_gbuf_entry_x80),
                                (x),
                                $sizeof_gbuf_entry
                            ),
                            $gbuf_entry_glyphinfo
                        )),
                    bkglyphinfo
                )));
                cptr.st1(gptr, 0);
            }
        }
    }
    {
        let i;
        for (i = 0; i < NHM.ROWNO; i++) {
            cptr.stI16o2(gg, i, 2, $instance_globals_g_gbuf_start, 79);
            cptr.stI16o2(gg, i, 2, $instance_globals_g_gbuf_stop, 0);
        }
    }
    ;

    /* after map update, before display_nhwindow(WIN_MAP) */
    if (cursor_on_u)
        (yield* Y.icall(curs()(WIN_MAP.v, cptr.ldI16(u), cptr.ldI16o(u, $you_uy))));  /* move cursor to the hero */

    (yield* Y.icall(display_nhwindow()(WIN_MAP.v, 0)));
    __static_flush_screen_flushing = 0;
}

