/* Called from mklev.  Scan the level and set the wall modes. */
/** C ref: display.c:3330 */
function set_wall_state() {
    let x;
    let y;

    for (x = 0; x < NHM.COLNO; x++)
        for (y = 0; y < NHM.ROWNO; y++)
            xy_set_wall_state(x, y);
}

