        cptr.st1o2(
            cptr.decay(nomux_buf[nomux_raw_row]),
            nomux_raw_col,
            $sizeof_nomux_cell,
            $nomux_cell_fg,
            nomux_fg_cur
        );
        cptr.st1o2(
            cptr.decay(nomux_buf[nomux_raw_row]),
            nomux_raw_col,
            $sizeof_nomux_cell,
            $nomux_cell_attr,
            nomux_attr_cur
        );
