        nomux_attr_cur = uchar(nomux_attr_cur | 2);
    for (let p = s; cptr.ld1s(p); p = cptr.add(p, 1))
        nomux_raw_putch(uchar(cptr.ld1s(p)));  /* puts() / tty_raw_print_bold both append a newline */
