            cptr.stI32o2(artiexist, a, $sizeof_arti_info, $arti_info_named, 1), ++ct;
        if (((aflags & NHM.ONAME_LEVEL_DEF) >>> 0) != 0)
            cptr.stI32o2(artiexist, a, $sizeof_arti_info, $arti_info_lvldef, 1), ++ct;
